    function ymd(d) { return d.getFullYear() + '. ' + (d.getMonth() + 1) + '. ' + d.getDate() + '.'; }
    function dayDiff(a, b) { return Math.round((Date.UTC(b.getFullYear(), b.getMonth(), b.getDate()) - Date.UTC(a.getFullYear(), a.getMonth(), a.getDate())) / 864e5); }
    function offName(d) { var w = d.getDay(); return hmap[(d.getMonth() + 1) + '-' + d.getDate()] || (w === 0 ? '일요일' : '토요일'); }

    // 실제 마감일: 법정 기한이 토·일·공휴일이면 그다음 첫 평일
    var ITEMS = EV.map(function (e, i) {
      var orig = dt(e[0], e[1]), due = orig;
      while (isOff(due)) due = addDays(due, 1);
      return { i: i, orig: orig, due: due, start: e[3] ? dt(e[2], e[3]) : null, name: e[4], tags: e[5], kind: e[6], note: e[7], flag: e[8] || '',
        ext: due - orig !== 0, why: due - orig !== 0 ? offName(orig) : '' };
    });
    ITEMS.sort(function (a, b) { return (a.due - b.due) || (a.i - b.i); });

    // ---------- 입력 ----------
    var chipBox = $('[data-chips]'), msg = $('[data-msg]'), result = $('[data-result]');
    var baseI = $('[data-base]'), baseText = $('[data-base-text]'), baseToggle = $('[data-base-toggle]');
    var sel = { w: 1, c: 1 }, cur = 0, list = [], base = null, lastText = '';
    TYPES.forEach(function (t) {
      var b = document.createElement('button');
      b.type = 'button'; b.className = 'ktc-chip'; b.setAttribute('data-t', t[0]); b.textContent = t[1];
      chipBox.appendChild(b);
    });
    chipBox.addEventListener('click', function (e) {
      var c = e.target.closest('[data-t]'); if (!c) return;
      var k = c.getAttribute('data-t');
      if (sel[k]) delete sel[k]; else sel[k] = 1;
      calc(true);
    });

    function today() { var n = new Date(); return new Date(n.getFullYear(), n.getMonth(), n.getDate()); }
    function getBase() {
      if (baseI.hidden) return today();
      var p = (baseI.value || '').split('-');
      if (p.length !== 3) return null;
      var d = new Date(+p[0], +p[1] - 1, +p[2]);
      return isNaN(d) ? null : d;
    }

    function hide(text, chips) {
      result.classList.remove('ktc-show');
      msg.textContent = text || '';
      chipBox.classList.toggle('ktc-bad', !!(text && chips));
      baseI.classList.toggle('ktc-bad', !!(text && !chips));
    }

    function calc(fromChip) {
      $$('[data-t]').forEach(function (c) { var on = !!sel[c.getAttribute('data-t')]; c.classList.toggle('ktc-on', on); c.setAttribute('aria-pressed', on); });
      var keys = Object.keys(sel);
      if (!keys.length) return hide(fromChip ? '유형을 하나 이상 골라 주세요.' : '', true);
      base = getBase();
      if (!base) { base = null; return hide('기준일을 다시 골라 주세요.', false); }
      if (!baseI.hidden && (base.getFullYear() < 2026 || base.getFullYear() > YEAR)) return hide('기준일은 2026. 1. 1.부터 2027. 12. 31. 사이로 골라 주세요.', false);
      msg.textContent = ''; chipBox.classList.remove('ktc-bad'); baseI.classList.remove('ktc-bad');
      list = ITEMS.filter(function (it) { return keys.some(function (k) { return it.tags.indexOf(k) >= 0; }); });
      var future = list.filter(function (it) { return dayDiff(base, it.due) >= 0; });
      var nx = future[0];
      if (nx) {
        var n = dayDiff(base, nx.due);
        $('[data-main-label]').textContent = '다음 마감까지';
        $('[data-big]').textContent = n === 0 ? 'D-day' : 'D-' + n;
        $('[data-main-sub]').textContent = nx.name;
        $('[data-main-date]').innerHTML = '<span class="ktc-nw">' + YEAR + '. ' + md(nx.due) + '</span>까지' + (nx.ext ? ' <span class="ktc-nw">(원래 ' + md(nx.orig) + ')</span>' : '');
        $('[data-next-list]').innerHTML = future.slice(1, 4).map(function (it) {
          var k = dayDiff(base, it.due);
          return '<li><b>' + (k === 0 ? 'D-day' : 'D-' + k) + '</b><span><span class="ktc-nw">' + md(it.due) + '</span> ' + it.name + '</span></li>';
        }).join('');
        cur = nx.due.getMonth();
      } else {
        $('[data-main-label]').textContent = '고른 유형의 2027년 마감';
        $('[data-big]').textContent = '완료';
        $('[data-main-sub]').textContent = '2027년 일정이 모두 지났어요';
        $('[data-main-date]').textContent = '2028년 일정은 새해에 다시 확인해 주세요.';
        $('[data-next-list]').innerHTML = '';
        cur = 11;
      }
      var extN = list.filter(function (it) { return it.ext; }).length;
      $('[data-count]').innerHTML = '2027년에 챙길 마감 <b>' + list.length + '건</b> · 주말·공휴일로 미뤄진 마감 <b>' + extN + '건</b>';
      result.classList.add('ktc-show');
      draw();
      makeText(keys, nx, future);
    }

    // ---------- 달력 ----------
    var tabs = $('[data-tabs]'), cal = $('[data-cal]');
    for (var m = 0; m < 12; m++) {
      var tb = document.createElement('button');
      tb.type = 'button'; tb.className = 'ktc-tab'; tb.setAttribute('role', 'tab'); tb.setAttribute('data-m', m);
      tb.textContent = (m + 1) + '월';
      tabs.appendChild(tb);
    }
    tabs.addEventListener('click', function (e) { var t = e.target.closest('[data-m]'); if (t) { cur = +t.getAttribute('data-m'); draw(); } });
    $('[data-prev]').addEventListener('click', function () { if (cur > 0) { cur--; draw(); } });
    $('[data-next]').addEventListener('click', function () { if (cur < 11) { cur++; draw(); } });
    var sx = null, sy = null;
    cal.addEventListener('touchstart', function (e) { sx = e.touches[0].clientX; sy = e.touches[0].clientY; }, { passive: true });
    cal.addEventListener('touchend', function (e) {
      if (sx === null) return;
      var dx = e.changedTouches[0].clientX - sx, dy = e.changedTouches[0].clientY - sy; sx = null;
      if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) * 1.5) {
        if (dx < 0 && cur < 11) { cur++; draw(); } else if (dx > 0 && cur > 0) { cur--; draw(); }
      }
    });

    function when(it) {
      var s = it.start ? '<span class="ktc-nw">' + md(it.start) + '</span> ~ ' : '';
      return s + '<span class="ktc-nw">' + md(it.due) + '</span>까지' +
        (it.ext ? '<span class="ktc-ext">원래 ' + md(it.orig) + ' → 연장</span>' : '');
    }

    function draw() {
      if (!base) return;
      $('[data-month-label]').textContent = YEAR + '년 ' + (cur + 1) + '월';
      $('[data-prev]').disabled = cur === 0; $('[data-next]').disabled = cur === 11;
      $$('[data-m]').forEach(function (t) {
        var mm = +t.getAttribute('data-m'), on = mm === cur;
        t.classList.toggle('ktc-on', on); t.setAttribute('aria-selected', on);
        t.classList.toggle('ktc-has', list.some(function (it) { return it.due.getMonth() === mm; }));
      });
      var byDay = {};
      list.forEach(function (it) { if (it.due.getMonth() === cur) (byDay[it.due.getDate()] = byDay[it.due.getDate()] || []).push(it); });
      var html = '';
      WD.forEach(function (w, i) { html += '<div class="ktc-wd' + (i === 0 ? ' ktc-sun' : i === 6 ? ' ktc-sat' : '') + '">' + w + '</div>'; });
      var first = new Date(YEAR, cur, 1), last = new Date(YEAR, cur + 1, 0).getDate();
      for (var i = 0; i < first.getDay(); i++) html += '<div class="ktc-day ktc-empty" aria-hidden="true"></div>';
      for (var d = 1; d <= last; d++) {
        var x = new Date(YEAR, cur, d), w = x.getDay(), h = hmap[(cur + 1) + '-' + d], c = 'ktc-day', its = byDay[d], tip = h || '';
        if (w === 0) c += ' ktc-sun'; if (w === 6) c += ' ktc-sat'; if (h) c += ' ktc-hol';
        if (its) { c += ' ktc-due'; if (dayDiff(base, x) < 0) c += ' ktc-past'; tip = its.map(function (it) { return it.name; }).join(', '); }
        if (base && dayDiff(base, x) === 0) c += ' ktc-today';
        html += '<div class="' + c + '" title="' + tip + '"><span class="ktc-num">' + d + '</span><span class="ktc-dots">' +
          (its ? its.slice(0, 3).map(function () { return '<i></i>'; }).join('') : '') + '</span></div>';
      }
      cal.innerHTML = html;
      var items = list.filter(function (it) { return it.due.getMonth() === cur; });
      $('[data-list]').innerHTML = items.length ? items.map(function (it) {
        var n = dayDiff(base, it.due), past = n < 0;
        return '<li class="ktc-item' + (past ? ' ktc-past' : '') + '"><span class="ktc-itop"><span class="ktc-iname">' + it.name +
          (it.flag ? '<span class="ktc-flag">' + it.flag + '</span>' : '') + '</span><span class="ktc-dd">' + (past ? '지남' : n === 0 ? 'D-day' : 'D-' + n) + '</span></span>' +
          '<span class="ktc-when">' + when(it) + '</span><span class="ktc-inote">' + it.kind + ' · ' + it.note + '</span></li>';
      }).join('') : '<li class="ktc-none">이달에는 고른 유형의 마감이 없어요.</li>';
    }

    function makeText(keys, nx, future) {
      var names = TYPES.filter(function (t) { return keys.indexOf(t[0]) >= 0; }).map(function (t) { return t[1]; }).join(', ');
      var t = '[2027년 내 세금 납부 일정 · ' + names + ']\n';
      if (nx) t += '다음 마감: ' + nx.name + ' ' + YEAR + '. ' + md(nx.due) + ' (D-' + dayDiff(base, nx.due) + ', ' + ymd(base) + ' 기준)\n';
      var mm = -1;
      list.forEach(function (it) {
        if (it.due.getMonth() !== mm) { mm = it.due.getMonth(); t += '\n' + (mm + 1) + '월\n'; }
        t += '- ' + md(it.due) + ' ' + it.name + (it.start ? ' (' + md(it.start) + '부터)' : '') + (it.ext ? ' ※ 원래 ' + md(it.orig) + ', ' + it.why + '이라 연장' : '') + '\n';
      });
      lastText = t + '\n※ 토·일·공휴일이면 다음 평일로 연장(국세기본법 제5조, 지방세기본법 제24조). 고지서의 기한이 우선이에요.';
    }

    baseToggle.addEventListener('click', function () {
      var open = baseI.hidden;
      baseI.hidden = !open;
      baseText.hidden = open;
      baseToggle.textContent = open ? '오늘로 되돌리기' : '기준일 바꾸기';
      if (open) {
        var t = today();
        if (t.getFullYear() < 2026 || t.getFullYear() > YEAR) t = new Date(YEAR, 0, 1);
        baseI.value = t.getFullYear() + '-' + ('0' + (t.getMonth() + 1)).slice(-2) + '-' + ('0' + t.getDate()).slice(-2);
        baseI.focus();
      }
      calc();
    });
    baseI.addEventListener('change', function () { calc(); });
    baseI.addEventListener('input', function () { calc(); });

    $('[data-reset]').addEventListener('click', function () {
      sel = {};
      if (!baseI.hidden) baseToggle.click(); else calc();
      var f = chipBox.querySelector('[data-t]'); if (f) f.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (er) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });

    calc();
  })();
  </script>
</div>
<!-- 2027 세금 납부 달력 위젯 끝 -->
<h2>실제 마감일 계산법 (주말·공휴일 연장)</h2>
<p>세금마다 법으로 정한 납부·신고 기한이 있어요. 그런데 그날이 쉬는 날이면 기한이 자동으로 미뤄져요. 국세(종합소득세, 부가가치세, 원천세 등)는 <strong>국세기본법 제5조</strong>, 지방세(자동차세, 재산세, 주민세 등)는 <strong>지방세기본법 제24조</strong>에 근거가 있어요.</p>
<ul>
  <li><strong>실제 마감일</strong> = 법정 기한이 토요일·일요일·공휴일(대체공휴일 포함)이면 그다음 첫 평일</li>
  <li>미뤄진 날까지 내면 <strong>가산세가 붙지 않아요</strong>. 하루라도 넘기면 원래 기한 기준으로 가산세가 계산돼요.</li>
</ul>
<p>예를 들어 2027년 10월 원천세 기한은 10월 10일인데 이날이 일요일이에요. 다음 날인 10월 11일(월)은 한글날 대체공휴일이라 또 쉬는 날이어서, 실제 마감은 <strong>10월 12일(화)</strong>이 돼요. 위 달력은 2027년 공휴일 24일(대체공휴일 7일 포함)을 모두 넣어 이렇게 계산했어요.</p>

<h2>2027년 월별 세금 납부·신고 일정</h2>
<p>개인이 주로 챙기는 세금만 모았어요. '실제 마감'은 주말·공휴일 연장을 반영한 날짜예요. 원천세(매월 10일)는 아래 표에서 따로 정리했어요.</p>
