    .khc .khc-list{list-style:none;margin-top:6px}
    .khc .khc-list li{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 0;border-top:1px solid #f0f2f6;font-size:14px}
    .khc .khc-list li:first-child{border-top:0}
    .khc .khc-name{word-break:keep-all}
    .khc .khc-name small{display:block;font-size:12px;color:var(--khc-sub)}
