    .khc .khc-tag.khc-pay{background:#f4f5f8;color:var(--khc-text)}
    .khc .khc-empty{margin-top:6px;font-size:13.5px;color:var(--khc-sub)}
    .khc .khc-tip{margin-top:8px;padding:12px 14px;border-radius:14px;background:#fff8e8;font-size:13.5px;color:#6a4b00}
