    var YEAR = 2027, WD = ['일', '월', '화', '수', '목', '금', '토'];
    // 음력 달이 시작하는 양력 날짜 [월, 일, 음력 달]. 한국 표준시(UTC+9) 합삭일 = 음력 1일. 2027년 윤달 없음.
    // 앞 두 줄은 2026년 음력 11월(2026. 12. 9. 시작)·12월. 마지막 줄 다음 달은 2028. 1. 27.(음력 2028년 1월 1일)
    var LSTART = [[1, 8, 12], [2, 7, 1], [3, 8, 2], [4, 7, 3], [5, 6, 4], [6, 5, 5], [7, 4, 6], [8, 2, 7], [9, 1, 8], [9, 30, 9], [10, 29, 10], [11, 28, 11], [12, 28, 12]];
    var PREV_START = new Date(2026, 11, 9); // 2026년 음력 11월 1일
    // 2027년 관공서 공휴일 (우주항공청 2027년 월력요항, 2026. 6. 발표). [월, 일, 이름, 달력 약칭]
    var HOLI = [
      [1, 1, '신정', '신정'],
      [2, 6, '설날 연휴', '설 연휴'], [2, 7, '설날', '설날'], [2, 8, '설날 연휴', '설 연휴'], [2, 9, '대체공휴일(설날)', '대체'],
      [3, 1, '삼일절', '삼일절'],
      [5, 1, '노동절', '노동절'], [5, 3, '대체공휴일(노동절)', '대체'], [5, 5, '어린이날', '어린이날'], [5, 13, '부처님오신날', '부처님 오신날'],
      [6, 6, '현충일', '현충일'],
      [7, 17, '제헌절', '제헌절'], [7, 19, '대체공휴일(제헌절)', '대체'],
      [8, 15, '광복절', '광복절'], [8, 16, '대체공휴일(광복절)', '대체'],
      [9, 14, '추석 연휴', '추석 연휴'], [9, 15, '추석', '추석'], [9, 16, '추석 연휴', '추석 연휴'],
      [10, 3, '개천절', '개천절'], [10, 4, '대체공휴일(개천절)', '대체'], [10, 9, '한글날', '한글날'], [10, 11, '대체공휴일(한글날)', '대체'],
      [12, 25, '성탄절', '성탄절'], [12, 27, '대체공휴일(성탄절)', '대체']
    ];
    var hmap = {};
    HOLI.forEach(function (h) { hmap[h[0] + '-' + h[1]] = h; });

    function key(d) { return (d.getMonth() + 1) + '-' + d.getDate(); }
    function dayDiff(a, b) { return Math.round((Date.UTC(b.getFullYear(), b.getMonth(), b.getDate()) - Date.UTC(a.getFullYear(), a.getMonth(), a.getDate())) / 864e5); }
    function md(d) { return (d.getMonth() + 1) + '. ' + d.getDate() + '.(' + WD[d.getDay()] + ')'; }
    function full(d) { return d.getFullYear() + '. ' + md(d); }

    // 2027년 모든 날의 음력과 손없는날 여부
    var DAYS = [], SON = [];
    (function () {
      var starts = LSTART.map(function (s) { return { d: new Date(YEAR, s[0] - 1, s[1]), m: s[2] }; });
      for (var d = new Date(YEAR, 0, 1); d.getFullYear() === YEAR; d = new Date(YEAR, d.getMonth(), d.getDate() + 1)) {
        var st = { d: PREV_START, m: 11 };
        for (var i = 0; i < starts.length; i++) if (starts[i].d <= d) st = starts[i];
        var ld = dayDiff(st.d, d) + 1, w = d.getDay(), h = hmap[key(d)];
        var o = { d: d, lm: st.m, ld: ld, ly: st.m >= 11 && d.getMonth() < 2 ? YEAR - 1 : YEAR, son: ld % 10 === 9 || ld % 10 === 0, hol: h, off: w === 0 || w === 6 || !!h };
        DAYS.push(o);
        if (o.son) SON.push(o);
      }
    })();
    function info(d) { return DAYS[dayDiff(new Date(YEAR, 0, 1), d)]; }
    function lunarText(o) { return '음력 ' + (o.ly !== YEAR ? o.ly + '년 ' : '') + o.lm + '월 ' + o.ld + '일'; }
    function kind(o) { return o.hol ? o.hol[2] : (o.d.getDay() === 0 ? '일요일' : o.d.getDay() === 6 ? '토요일' : '평일'); }

    // ---------- 가장 가까운 손없는날 ----------
    function today() { var n = new Date(); return new Date(n.getFullYear(), n.getMonth(), n.getDate()); }
    function drawNear() {
      var t = today(), next = null;
      for (var i = 0; i < SON.length; i++) if (SON[i].d >= t) { next = SON[i]; break; }
      var label = $('[data-near-label]'), big = $('[data-near-big]'), sub = $('[data-near-sub]');
      if (!next) {
        label.textContent = '2027년 손없는날';
        big.textContent = '끝';
        sub.textContent = '2027년 손없는날이 모두 지났어요.';
        return;
      }
      var n = dayDiff(t, next.d);
      label.textContent = t.getFullYear() < YEAR ? '가장 가까운 2027년 손없는날' : '오늘 이후 가장 가까운 손없는날';
      big.textContent = n === 0 ? '오늘' : 'D-' + n;
      sub.innerHTML = '<b class="kmv-nw">' + full(next.d) + '</b> <span class="kmv-nw">' + lunarText(next) + '</span>' + (next.off ? ' <span class="kmv-nw">· ' + kind(next) + '</span>' : '');
    }

    // ---------- 달력 ----------
    var cur = 0, onlyOff = false, pickKey = null;
    var now = today();
    if (now.getFullYear() === YEAR) cur = now.getMonth();
    var tabs = $('[data-tabs]'), cal = $('[data-cal]'), list = $('[data-list]'), offBtn = $('[data-off]');
    for (var m = 0; m < 12; m++) {
      var b = document.createElement('button');
      b.type = 'button'; b.className = 'kmv-tab'; b.setAttribute('role', 'tab'); b.setAttribute('data-tab', m);
      b.textContent = (m + 1) + '월';
      tabs.appendChild(b);
    }
    tabs.addEventListener('click', function (e) { var t = e.target.closest('[data-tab]'); if (t) { cur = +t.getAttribute('data-tab'); draw(); } });
    $('[data-prev]').addEventListener('click', function () { if (cur > 0) { cur--; draw(); } });
    $('[data-next]').addEventListener('click', function () { if (cur < 11) { cur++; draw(); } });
    offBtn.addEventListener('click', function () { onlyOff = !onlyOff; offBtn.setAttribute('aria-pressed', onlyOff); draw(); });

    var sx = null, sy = null;
    cal.addEventListener('touchstart', function (e) { sx = e.touches[0].clientX; sy = e.touches[0].clientY; }, { passive: true });
    cal.addEventListener('touchend', function (e) {
      if (sx === null) return;
      var dx = e.changedTouches[0].clientX - sx, dy = e.changedTouches[0].clientY - sy; sx = null;
      if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) * 1.5) {
        if (dx < 0 && cur < 11) { cur++; draw(); } else if (dx > 0 && cur > 0) { cur--; draw(); }
      }
    });
    cal.addEventListener('click', function (e) {
      var c = e.target.closest('[data-day]'); if (!c) return;
      mI.value = cur + 1; dI.value = c.getAttribute('data-day'); calc();
    });

    function show(o) { return o.son && (!onlyOff || o.off); }

    function draw() {
      $('[data-month-label]').textContent = YEAR + '년 ' + (cur + 1) + '월';
      $('[data-prev]').disabled = cur === 0; $('[data-next]').disabled = cur === 11;
      $$('[data-tab]').forEach(function (t) { var on = +t.getAttribute('data-tab') === cur; t.classList.toggle('kmv-on', on); t.setAttribute('aria-selected', on); });
      var html = '';
      WD.forEach(function (w, i) { html += '<div class="kmv-wd' + (i === 0 ? ' kmv-sun' : i === 6 ? ' kmv-sat' : '') + '">' + w + '</div>'; });
      var first = new Date(YEAR, cur, 1), last = new Date(YEAR, cur + 1, 0).getDate(), tk = now.getFullYear() === YEAR ? key(now) : '';
      for (var i = 0; i < first.getDay(); i++) html += '<div class="kmv-day kmv-empty" aria-hidden="true"></div>';
      for (var dd = 1; dd <= last; dd++) {
        var o = info(new Date(YEAR, cur, dd)), w = o.d.getDay(), c = 'kmv-day';
        if (w === 0) c += ' kmv-sun'; if (w === 6) c += ' kmv-sat'; if (o.hol) c += ' kmv-hol';
        if (show(o)) c += ' kmv-son' + (o.off ? ' kmv-off' : '');
        if (key(o.d) === pickKey) c += ' kmv-pick';
        if (key(o.d) === tk) c += ' kmv-today';
        var lun = o.ld === 1 ? o.lm + '.1' : String(o.ld);
        var aria = (cur + 1) + '월 ' + dd + '일 ' + WD[w] + '요일, ' + lunarText(o) + (o.son ? ', 손없는날' : '') + (o.hol ? ', ' + o.hol[2] : '');
        html += '<button type="button" class="' + c + '" data-day="' + dd + '" aria-label="' + aria + '"><span class="kmv-num">' + dd + '</span><span class="kmv-lun">' + lun + '</span>' +
          (o.hol ? '<span class="kmv-hn">' + o.hol[3] + '</span>' : '') + '</button>';
      }
      cal.innerHTML = html;
      var all = SON.filter(function (o) { return o.d.getMonth() === cur; });
      var items = all.filter(show);
      var offCnt = all.filter(function (o) { return o.off; }).length;
      $('[data-month-count]').textContent = '손없는날 ' + all.length + '일 · 주말·공휴일 ' + offCnt + '일';
      list.innerHTML = items.length ? items.map(function (o) {
        return '<li><b>' + md(o.d) + '</b><span class="kmv-l2">' + lunarText(o) + '</span>' +
          (o.off ? '<span class="kmv-tag' + (o.hol ? ' kmv-tag-h' : '') + '">' + (o.hol ? '공휴일' : '주말') + '</span>' : '') + '</li>';
      }).join('') : '<li class="kmv-none">이달에는 주말·공휴일 손없는날이 없어요.</li>';
    }

    // ---------- 날짜 확인 ----------
    var mI = $('[data-m]'), dI = $('[data-d]'), msg = $('[data-msg]'), result = $('[data-result]'), lastText = '';

    function hide(text) {
      result.classList.remove('kmv-show');
      msg.textContent = text || '';
      mI.classList.toggle('kmv-bad', !!text); dI.classList.toggle('kmv-bad', !!text);
      if (pickKey) { pickKey = null; draw(); }
    }

    function sonDesc(o, base) {
      var n = dayDiff(base, o.d);
      return lunarText(o) + ' · ' + (n > 0 ? n + '일 뒤' : -n + '일 전') + (o.off ? ' · ' + kind(o) : '');
    }

    function calc() {
      var mv = mI.value, dv = dI.value;
      if (!mv || !dv) return hide('');
      var m = +mv, d = +dv, dt = new Date(YEAR, m - 1, d);
      if (m < 1 || m > 12) return hide('월은 1~12 사이로 입력해 주세요.');
      if (d < 1 || dt.getMonth() !== m - 1) return hide('2027년 ' + m + '월에는 ' + d + '일이 없어요. 날짜를 다시 확인해 주세요.');
      msg.textContent = ''; mI.classList.remove('kmv-bad'); dI.classList.remove('kmv-bad');
      var o = info(dt), prev = null, next = null;
      SON.forEach(function (s) { if (s.d < dt) prev = s; else if (s.d > dt && !next) next = s; });
      var v = $('[data-verdict]');
      v.classList.toggle('kmv-no', !o.son);
      $('[data-vt]').textContent = o.son ? '손없는날이에요' : '손없는날이 아니에요';
      $('[data-vs]').innerHTML = '<span class="kmv-nw">' + full(dt) + '</span> = <span class="kmv-nw">' + lunarText(o) + '</span>' +
        (o.off ? ' <span class="kmv-nw">· ' + kind(o) + '</span>' : '');
      $('[data-prev-son]').textContent = prev ? md(prev.d) : '없음';
      $('[data-prev-son-s]').textContent = prev ? sonDesc(prev, dt) : '2027년 첫 손없는날은 1. 6.(수)';
      $('[data-next-son]').textContent = next ? md(next.d) : '없음';
      $('[data-next-son-s]').textContent = next ? sonDesc(next, dt) : '2027년 마지막 손없는날이 지났어요';
      result.classList.add('kmv-show');
      pickKey = key(dt);
      if (cur !== m - 1) cur = m - 1;
      draw();
      lastText = '[2027년 손없는날 확인]\n' + full(dt) + ' = ' + lunarText(o) + (o.off ? ' (' + kind(o) + ')' : '') + '\n→ ' + (o.son ? '손없는날이에요' : '손없는날이 아니에요') +
        '\n바로 앞 손없는날: ' + (prev ? full(prev.d) + ' ' + lunarText(prev) : '없음') +
        '\n바로 뒤 손없는날: ' + (next ? full(next.d) + ' ' + lunarText(next) : '없음') +
        '\n\n' + (m) + '월 손없는날: ' + SON.filter(function (s) { return s.d.getMonth() === m - 1; }).map(function (s) { return md(s.d); }).join(', ') +
        '\n※ 손없는날 = 음력 9·10·19·20·29·30일';
    }

    function bind(input, next) {
      input.addEventListener('input', function () {
        var v = input.value.replace(/\D/g, '').slice(0, 2);
        if (v !== input.value) input.value = v;
        if (next && (v.length === 2 || (v.length === 1 && +v > 1))) next.focus();
