    ];
    EV.forEach(function (e, i) { e.date = new Date(YEAR, e[0] - 1, e[1]); e.cats = e[2].split(' '); e.i = i; });
    function has(e, c) { return e.cats.indexOf(c) > -1; }
    // 이름에서 절기 이름만 / 기념일 이름만 뽑기 ('청명 · 식목일' → 절기 '청명', 기념일 '식목일')
    function termName(e) { return e[3].split(' · ')[0]; }
    function eventName(e) { return has(e, 'term') && e[3].indexOf(' · ') > -1 ? e[3].split(' · ').slice(1).join(' · ') : e[3]; }
    function isEvent(e) { return e.cats.some(function (c) { return c !== 'term'; }); }

    function fmt(d) { return d.getFullYear() + '. ' + (d.getMonth() + 1) + '. ' + d.getDate() + '.'; }
    function md(d) { return (d.getMonth() + 1) + '. ' + d.getDate() + '.(' + WD[d.getDay()] + ')'; }
    function dayDiff(a, b) { return Math.round((Date.UTC(b.getFullYear(), b.getMonth(), b.getDate()) - Date.UTC(a.getFullYear(), a.getMonth(), a.getDate())) / 864e5); }
    function dd(n) { return n === 0 ? 'D-Day' : 'D-' + n.toLocaleString('ko-KR'); }
    function isRed(e) { return has(e, 'hol') || e.date.getDay() === 0; }

    var yI = $('[data-y]'), mI = $('[data-m]'), dI = $('[data-d]'), msg = $('[data-msg]'), result = $('[data-result]');
    var cur = 0, filter = 'all', open = -1, base = null, nextT = null, nextE = null;

    // ---------- 월 탭 · 필터 칩 ----------
    var tabs = $('[data-tabs]'), chips = $('[data-chips]'), list = $('[data-list]');
    for (var m = 0; m < 12; m++) {
      var b = document.createElement('button');
      b.type = 'button'; b.className = 'kse-tab'; b.setAttribute('role', 'tab'); b.setAttribute('data-mo', m); b.textContent = (m + 1) + '월';
      tabs.appendChild(b);
    }
    [['all', '전체']].concat(Object.keys(CAT).map(function (k) { return [k, CAT[k]]; })).forEach(function (c) {
      var b = document.createElement('button');
      b.type = 'button'; b.className = 'kse-chip'; b.setAttribute('data-f', c[0]); b.textContent = c[1];
      chips.appendChild(b);
    });
    tabs.addEventListener('click', function (e) { var t = e.target.closest('[data-mo]'); if (t) { cur = +t.getAttribute('data-mo'); open = -1; draw(); } });
    chips.addEventListener('click', function (e) { var t = e.target.closest('[data-f]'); if (t) { filter = t.getAttribute('data-f'); open = -1; draw(); } });
    $('[data-prev]').addEventListener('click', function () { if (cur > 0) { cur--; open = -1; draw(); } });
    $('[data-next]').addEventListener('click', function () { if (cur < 11) { cur++; open = -1; draw(); } });
    list.addEventListener('click', function (e) {
      var t = e.target.closest('[data-i]'); if (!t) return;
      var i = +t.getAttribute('data-i'); open = open === i ? -1 : i; draw();
    });

    function shown() {
      return EV.filter(function (e) { return e[0] === cur + 1 && (filter === 'all' || has(e, filter)); });
    }

    function draw() {
      $('[data-month-label]').textContent = YEAR + '년 ' + (cur + 1) + '월';
      $('[data-prev]').disabled = cur === 0; $('[data-next]').disabled = cur === 11;
      $$('[data-mo]').forEach(function (t) { var on = +t.getAttribute('data-mo') === cur; t.classList.toggle('kse-on', on); t.setAttribute('aria-selected', on); });
      $$('[data-f]').forEach(function (t) { var on = t.getAttribute('data-f') === filter; t.classList.toggle('kse-on', on); t.setAttribute('aria-pressed', on); });
      var items = shown();
      list.innerHTML = items.length ? items.map(function (e) {
        var past = base && dayDiff(base, e.date) < 0, on = open === e.i;
        var tags = e.cats.map(function (c) { return '<span class="kse-tag kse-t-' + c + '">' + CAT[c] + '</span>'; }).join('');
        return '<li><button type="button" class="kse-item' + (on ? ' kse-on' : '') + (past ? ' kse-past' : '') + '" data-i="' + e.i + '" aria-expanded="' + on + '">' +
          '<span class="kse-itop"><span class="kse-date' + (isRed(e) ? ' kse-red' : '') + '">' + md(e.date) + '</span><span class="kse-name">' + e[3] + '</span>' + tags + '</span>' +
          (on ? '<span class="kse-idesc">' + e[4] + '</span>' : '') + '</button></li>';
      }).join('') : '<li class="kse-none">이달에는 ' + (filter === 'all' ? '' : CAT[filter] + ' ') + '일정이 없어요.</li>';
    }

    // ---------- 기준일 · D-day ----------
    function onlyNum(el) { var v = el.value.replace(/[^\d]/g, ''); if (v !== el.value) el.value = v; }
    [yI, mI, dI].forEach(function (el) { el.addEventListener('input', function () { onlyNum(el); calc(); }); });

    function bad(text, els) {
      result.classList.remove('kse-show');
      msg.textContent = text || '';
      [yI, mI, dI].forEach(function (el) { el.classList.toggle('kse-bad', !!text && els.indexOf(el) > -1); });
      base = null; nextT = nextE = null; draw();
    }

    function setCard(k, e, nameFn) {
      if (!e) {
        $('[data-' + k + '-dd]').textContent = '종료';
        $('[data-' + k + '-name]').textContent = '2027년 일정이 모두 지났어요';
        $('[data-' + k + '-date]').textContent = '';
        return;
      }
      $('[data-' + k + '-dd]').textContent = dd(dayDiff(base, e.date));
      $('[data-' + k + '-name]').textContent = nameFn(e);
      $('[data-' + k + '-date]').innerHTML = '<span class="kse-nw">' + fmt(e.date) + '(' + WD[e.date.getDay()] + ')</span>';
    }

    function calc() {
      var ys = yI.value, ms = mI.value, ds = dI.value;
      if (!ys && !ms && !ds) return bad('', []);
      if (ys.length < 4 || !ms || !ds) {
        if (ys && ys.length < 4 && (ms || ds)) return bad('연도는 4자리로 입력해 주세요.', [yI]);
        return bad('', []);
      }
      var y = +ys, mo = +ms, d = +ds;
      if (y < 1900 || y > 2100) return bad('연도는 1900~2100 사이로 입력해 주세요.', [yI]);
      if (mo < 1 || mo > 12) return bad('월은 1~12 사이로 입력해 주세요.', [mI]);
      var last = new Date(y, mo, 0).getDate();
      if (d < 1 || d > last) return bad(y + '년 ' + mo + '월은 ' + last + '일까지 있어요.', [dI]);
      msg.textContent = ''; [yI, mI, dI].forEach(function (el) { el.classList.remove('kse-bad'); });
      base = new Date(y, mo - 1, d);
      var up = EV.filter(function (e) { return dayDiff(base, e.date) >= 0; });
      nextT = up.filter(function (e) { return has(e, 'term'); })[0] || null;
      nextE = up.filter(isEvent)[0] || null;
      setCard('t', nextT, termName);
      setCard('e', nextE, eventName);
      cur = y < YEAR ? 0 : y > YEAR ? 11 : mo - 1;
      open = -1; draw();
      result.classList.add('kse-show');
    }

    function fillToday() {
      var n = new Date();
      yI.value = n.getFullYear(); mI.value = n.getMonth() + 1; dI.value = n.getDate();
      calc();
    }
    $('[data-today]').addEventListener('click', fillToday);
    $('[data-reset]').addEventListener('click', function () { filter = 'all'; fillToday(); yI.focus(); });

    function copyText() {
      var out = '[2027년 24절기·기념일 달력]\n';
      if (base) {
        out += '기준일 ' + fmt(base) + '\n';
        out += '다음 절기: ' + (nextT ? termName(nextT) + ' ' + fmt(nextT.date) + ' (' + dd(dayDiff(base, nextT.date)) + ')' : '2027년 일정 종료') + '\n';
        out += '다음 기념일: ' + (nextE ? eventName(nextE) + ' ' + fmt(nextE.date) + ' (' + dd(dayDiff(base, nextE.date)) + ')' : '2027년 일정 종료') + '\n';
      }
      var items = shown();
      out += '\n' + YEAR + '년 ' + (cur + 1) + '월' + (filter === 'all' ? '' : ' · ' + CAT[filter]) + '\n';
      out += items.length ? items.map(function (e) { return md(e.date) + ' ' + e[3]; }).join('\n') : '일정 없음';
      return out + '\n\n※ 공휴일은 2027년 월력요항 기준, 임시공휴일 지정 시 바뀔 수 있어요.';
    }

    $('[data-copy]').addEventListener('click', function () {
      var btn = this, text = copyText();
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = text; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (er) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text).then(done, fallback);
      else fallback();
    });

    fillToday();
  })();
  </script>
</div>
