      <p class="krs-note">기한은 법령과 각 기관 안내 기준이에요. 마지막 날이 토·일·공휴일이면 다음 평일로 옮겨 계산했어요(실업급여 수급기간 제외). 개인 상황에 따라 다를 수 있으니 신청 전 해당 기관에서 한 번 더 확인하세요.</p>
      <div class="krs-actions">
        <button type="button" class="krs-btn" data-reset>다시 입력</button>
        <button type="button" class="krs-btn krs-primary" data-copy>결과 복사</button>
      </div>
    </div>
  </div>

  <script>
  (function () {
    var me = document.currentScript || (function (s) { return s[s.length - 1]; })(document.getElementsByTagName('script'));
    var root = me.closest('[data-krs]');
    if (!root || root.__krs) return;
    root.__krs = true;

    var $ = function (s) { return root.querySelector(s); };
    var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    var lastI = $('[data-last]'), msg = $('[data-msg]'), result = $('[data-result]'), listEl = $('[data-list]');
    var WD = ['일', '월', '화', '수', '목', '금', '토'];
    var MIN = '2025-01-01', MAX = '2027-12-31';
    var state = { reason: 'inv', job: 'no', dep: 'unk' };
    var done = {}, lastText = '';

    // 관공서 공휴일·대체공휴일·임시공휴일 (2026·2027년은 월력요항 기준 전체, 그 밖의 해는 양력 고정 공휴일만)
    var HOL = {
      2026: ['1-1', '2-16', '2-17', '2-18', '3-1', '3-2', '5-1', '5-5', '5-24', '5-25', '6-3', '6-6', '7-17', '8-15', '8-17', '9-24', '9-25', '9-26', '10-3', '10-5', '10-9', '12-25'],
      2027: ['1-1', '2-6', '2-7', '2-8', '2-9', '3-1', '5-1', '5-3', '5-5', '5-13', '6-6', '7-17', '7-19', '8-15', '8-16', '9-14', '9-15', '9-16', '10-3', '10-4', '10-9', '10-11', '12-25', '12-27']
    };
    var FIXED = ['1-1', '3-1', '5-5', '6-6', '8-15', '10-3', '10-9', '12-25'];
    var FIXED_2026 = ['5-1', '7-17']; // 노동절·제헌절: 2026년부터 공휴일

    function today() { var n = new Date(); return new Date(n.getFullYear(), n.getMonth(), n.getDate()); }
    function addDays(d, n) { return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n); }
    // n개월 뒤 같은 날. 그 달에 같은 날이 없으면 그 달 말일 (민법 제160조 제3항)
    function addMonths(d, n) {
      var y = d.getFullYear(), m = d.getMonth() + n, last = new Date(y, m + 1, 0).getDate();
      return new Date(y, m, Math.min(d.getDate(), last));
    }
    function dayDiff(a, b) { return Math.round((Date.UTC(b.getFullYear(), b.getMonth(), b.getDate()) - Date.UTC(a.getFullYear(), a.getMonth(), a.getDate())) / 864e5); }
    function fmt(d) { return d.getFullYear() + '. ' + (d.getMonth() + 1) + '. ' + d.getDate() + '.(' + WD[d.getDay()] + ')'; }
    function md(d) { return (d.getMonth() + 1) + '-' + d.getDate(); }
    function isHoliday(d) {
      var y = d.getFullYear(), k = md(d);
      if (HOL[y]) return HOL[y].indexOf(k) >= 0;
      return FIXED.indexOf(k) >= 0 || (y >= 2026 && FIXED_2026.indexOf(k) >= 0);
    }
    function isRest(d) { var w = d.getDay(); return w === 0 || w === 6 || isHoliday(d); }
    // 기간의 말일이 토요일·공휴일이면 그다음 날 만료 (민법 제161조, 국세기본법 제5조)
    function nextWork(d) { var x = d; while (isRest(x)) x = addDays(x, 1); return x; }
    function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }

    function parse(v) {
      var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v || '');
      if (!m) return null;
      var d = new Date(+m[1], +m[2] - 1, +m[3]);
      return d.getMonth() === +m[2] - 1 ? d : null;
    }

    // 할 일 목록 만들기. L = 마지막 근무일, Q = 다음 날(퇴직일·자격 상실일)
    function build(L) {
      var Q = addDays(L, 1), inv = state.reason === 'inv', job = state.job === 'yes', dep = state.dep;
      var pensionDue = new Date(Q.getFullYear(), Q.getMonth() + 1, 15);
      var items = [];
      function add(o) { items.push(o); }

      add({ id: 'irp', kind: '권장', lv: 2, date: L, title: 'IRP 계좌 만들고 회사에 알려 주기',
        where: '은행·증권사 앱에서 개인형퇴직연금(IRP) 개설 → 회사 담당자에게 계좌 전달',
        docs: '신분증, 본인 명의 계좌',
        miss: '만 55세 전에 퇴직하면 퇴직금은 IRP로 받는 게 원칙이에요. 계좌가 없으면 지급이 늦어질 수 있어요.',
        late: '현금으로 이미 받았다면, 받은 날부터 60일 안에 IRP에 넣으면 떼인 퇴직소득세를 돌려받을 수 있어요.' });

      if (!job) {
        add({ id: 'cert', kind: '권장', lv: inv ? 1 : 3, date: Q, title: '회사에 이직확인서 처리 요청',
          where: '전 직장 인사·노무 담당자 (처리 여부는 고용24에서 조회)',
          docs: '없음 (요청 사실을 문자·메일로 남겨 두면 좋아요)',
          miss: '이직확인서가 고용센터에 들어가야 실업급여 수급자격을 판단해요. 회사는 요청받은 날부터 10일 안에 내야 해요.',
          late: '아직 처리 전이면 지금 요청하세요. 10일이 지나도 안 되면 관할 고용센터에 알리세요.' });
        add({ id: 'ui', kind: '권장', lv: inv ? 1 : 3, date: Q,
          title: inv ? '고용24 구직신청 → 실업급여 신청' : '실업급여 대상인지 확인 (자발적 퇴사)',
          where: '고용24 누리집·앱에서 구직신청과 수급자격 신청자 온라인 교육 → 거주지 관할 고용센터 방문',
          docs: '신분증, 본인 명의 통장',
          miss: inv ? '실업급여는 퇴사 다음 날부터 12개월 안에만 받을 수 있어요. 늦게 신청할수록 다 못 받고 남은 날이 사라질 수 있어요.'
                    : '개인 사정 퇴사는 원칙적으로 대상이 아니지만, 임금 체불·통근 곤란 등 정당한 사유가 있으면 받을 수 있어요.',
          late: '퇴사 다음 날부터 12개월(수급기간)이 남아 있다면 지금이라도 신청하세요.' });
      }

      add({ id: 'sev', kind: '법정 기한', lv: 1, date: nextWork(addDays(L, 14)), raw: addDays(L, 14), title: '퇴직금 받기',
        where: '전 직장 (퇴직연금 가입 회사는 퇴직연금 금융회사를 통해 지급)',
        docs: '없음 (1년 이상, 주 15시간 이상 일했다면 대상)',
        miss: '퇴직일부터 14일 안에 줘야 해요. 당사자가 합의하면 늦출 수 있고, 늦으면 지연이자(연 20%)가 붙어요.',
        late: '아직 못 받았다면 회사에 청구하고, 그래도 안 주면 고용노동부에 진정할 수 있어요. 퇴직금 청구권은 3년이 지나면 사라져요.' });

      add({ id: 'pay', kind: '법정 기한', lv: 1, date: nextWork(addDays(L, 14)), raw: addDays(L, 14), title: '마지막 월급·미사용 연차수당 받기',
        where: '전 직장 (급여명세서로 일할 계산·연차수당 확인)',
        docs: '급여명세서, 남은 연차 일수',
        miss: '임금, 쓰지 못한 연차수당 등 모든 금품은 퇴직일부터 14일 안에 정산해야 해요.',
        late: '빠진 돈이 있으면 회사에 요청하고, 안 주면 고용노동부에 진정할 수 있어요. 임금 청구권은 3년이 지나면 사라져요.' });

      add({ id: 'ins', kind: '회사가 할 일', lv: 3, date: nextWork(pensionDue), raw: pensionDue, title: '4대보험 자격 상실 처리됐는지 확인',
        where: '4대사회보험 정보연계센터 또는 건강보험·국민연금 앱에서 자격 조회',
        docs: '없음 (신고는 회사 몫)',
        miss: '회사는 건강보험은 상실일부터 14일 안에, 국민연금·고용보험은 다음 달 15일까지 신고해야 해요. 늦으면 지역보험 전환이나 실업급여 신청이 꼬일 수 있어요.',
        late: '아직 직장가입자로 남아 있으면 회사에 상실신고를 요청하세요.' });

      if (!job) {
        add({ id: 'nps', kind: '법정 기한', lv: 2, date: nextWork(pensionDue), raw: pensionDue, title: '국민연금 지역가입 신고 또는 납부예외 신청',
          where: '국민연금공단 누리집·‘내 곁에 국민연금’ 앱, 전화 1355, 가까운 지사',
          docs: '퇴사를 확인할 수 있는 서류(경력증명서 등)',
          miss: '소득이 없으면 납부예외를 신청해 보험료를 쉴 수 있어요(그 기간은 가입기간에서 빠져요). 만 60세 이상이거나 소득 있는 배우자가 있으면 대상이 아닐 수 있어요.' +
                (inv ? ' 실업급여를 받으면 보험료 75%를 지원하는 실업크레딧도 확인해 보세요.' : ''),
          late: '지금이라도 신고·신청할 수 있어요. 이미 고지된 보험료 처리는 공단(1355)에 물어보세요.' });

        if (dep !== 'no') {
          add({ id: 'dep', kind: '법정 기한', lv: dep === 'yes' ? 1 : 2, date: nextWork(addDays(L, 90)), raw: addDays(L, 90), title: '가족의 건강보험 피부양자로 등록',
            where: '국민건강보험공단(The건강보험 앱·누리집, 1577-1000) 또는 가족 회사의 담당자',
            docs: '가족관계증명서 등 (공단에서 확인 가능하면 생략)',
            miss: '자격이 바뀐 날(퇴사 다음 날)부터 90일 안에 신고하면 그날로 소급돼, 그사이 지역보험료를 내지 않아도 돼요.',
            late: '지금도 등록할 수 있지만 신고한 날부터 인정돼서, 그 전까지의 지역보험료는 내야 해요.' });
        }
        if (dep !== 'yes') {
          add({ id: 'cont', kind: '고지서 기준', lv: 2, date: null, sort: addDays(nextWork(pensionDue), 1), title: '첫 지역보험료 고지서 받으면 → 임의계속가입 비교',
            where: '국민건강보험공단(The건강보험 앱·누리집, 1577-1000)',
            docs: '없음 (공단이 직권으로 지역가입자로 바꾸고 고지서를 보내요)',
            miss: '퇴직 전 18개월 중 직장가입 기간이 1년 이상이면 최대 36개월 직장 때 기준으로 낼 수 있어요. 첫 고지서 납부기한부터 2개월이 지나기 전에 신청해야 해요.',
            late: '' });
        }
      }

      if (!job && inv) {
        var uiEnd = addDays(addMonths(Q, 12), -1);
        add({ id: 'uiend', kind: '법정 기한', lv: 2, date: uiEnd, title: '실업급여 수급기간 끝 (퇴사 다음 날부터 12개월)',
          where: '고용24 (남은 지급일수 확인)',
          docs: '없음',
          miss: '이날이 지나면 받을 날이 남아 있어도 더 받을 수 없어요. 임신·출산·육아, 질병 등으로 취업할 수 없으면 수급기간 연기를 신청할 수 있어요.',
          late: '수급기간이 끝나 남은 구직급여는 받을 수 없어요.' });
      }

      var taxRaw = new Date(L.getFullYear() + 1, 4, 31);
      add({ id: 'tax', kind: '법정 기한', lv: 2, date: nextWork(taxRaw), raw: taxRaw,
        title: job ? '연말정산: 새 회사에 합산 또는 5월 종합소득세 신고' : '5월 종합소득세 신고로 연말정산 마무리',
        where: '홈택스·손택스 (종합소득세 신고)' + (job ? ', 같은 해 새 회사에 입사하면 새 회사 연말정산' : ''),
        docs: '전 직장 근로소득 원천징수영수증, 의료비·카드 등 공제 자료',
        miss: '퇴사할 때 회사가 하는 연말정산은 기본공제 위주라 빠진 공제가 많아요. ' + (job ? '같은 해에 입사하면 새 회사에 전 직장 원천징수영수증을 내 합산하고, 해를 넘겨 입사하면 5월에 직접 신고해요.' : (L.getFullYear() + 1) + '년 5월 1일~31일 종합소득세 신고 때 반영하면 환급받을 수 있어요.'),
        late: '기한이 지나도 5년 안에는 경정청구 등으로 빠진 공제를 돌려받을 수 있어요.' });

      items.forEach(function (it) { it.key = it.date || it.sort; });
      items.sort(function (a, b) { return a.key - b.key || a.lv - b.lv; });
      return items;
    }

    function dlabel(n) { return n === 0 ? '오늘까지' : n > 0 ? 'D-' + n : -n + '일 지남'; }

    function render(L) {
      var t = today(), items = build(L), html = '', copy = [], next = null, pastCount = 0, outside = false;
      items.forEach(function (it) {
        var n = it.date ? dayDiff(t, it.date) : null, past = n !== null && n < 0;
        if (past) pastCount++;
        if (!past && n !== null && !next && it.kind !== '권장' && it.kind !== '회사가 할 일') next = { it: it, n: n };
        if (it.date && !HOL[it.date.getFullYear()]) outside = true;
        var lvTxt = it.lv === 1 ? '꼭 챙기기' : it.lv === 2 ? '중요' : '참고';
        var ddCls = past ? ' krs-dd-past' : (n !== null && n <= 7 ? ' krs-dd-soon' : '');
        var on = !!done[it.id];
        html += '<li class="krs-item' + (past ? ' krs-past' : '') + (on ? ' krs-done' : '') + '">' +
          '<input type="checkbox" class="krs-check" data-id="' + it.id + '"' + (on ? ' checked' : '') + ' aria-label="' + esc(it.title) + ' 완료">' +
          '<div class="krs-item-body"><div class="krs-item-top">' +
          '<span class="krs-date">' + (it.date ? fmt(it.date) : '고지서 받으면') + '</span>' +
          (n !== null ? '<span class="krs-dd' + ddCls + '">' + (past ? dlabel(n) : (it.kind === '권장' && n >= 0 ? (n === 0 ? '오늘' : 'D-' + n) : dlabel(n))) + '</span>' : '') +
          '<span class="krs-badge krs-b' + it.lv + '">' + lvTxt + '</span>' +
          '<span class="krs-badge">' + it.kind + '</span></div>' +
          '<p class="krs-item-t">' + esc(it.title) + '</p>' +
          (it.raw && it.date && dayDiff(it.raw, it.date) > 0 ? '<p class="krs-shift">원래 기한 ' + fmt(it.raw) + ' → 휴일이라 다음 평일로 미뤘어요.</p>' : '') +
          '<div class="krs-rows"><p><b>어디서</b>' + esc(it.where) + '</p><p><b>필요 서류</b>' + esc(it.docs) + '</p><p><b>놓치면</b>' + esc(it.miss) + '</p></div></div>' +
          (past && it.late ? '<p class="krs-late">지났어요. ' + esc(it.late) + '</p>' : '') +
          '</li>';
        copy.push((on ? '☑ ' : '☐ ') + (it.date ? fmt(it.date) : '고지서 받으면') + ' ' + it.title + ' [' + it.kind + (n !== null ? ', ' + dlabel(n) : '') + ']');
      });
      listEl.innerHTML = '<p class="krs-sec">할 일 ' + items.length + '개 · 날짜순</p><ul class="krs-list">' + html + '</ul>';

      if (next) {
        $('[data-main-label]').textContent = '다음 기한까지';
        $('[data-big]').textContent = next.n === 0 ? '오늘' : 'D-' + next.n;
        $('[data-big-sub]').innerHTML = esc(next.it.title) + ' · <span class="krs-nw">' + fmt(next.it.date) + '</span>';
      } else {
        $('[data-main-label]').textContent = '남은 기한';
        $('[data-big]').textContent = '없음';
        $('[data-big-sub]').textContent = '날짜가 정해진 기한이 모두 지났어요.';
      }
      $('[data-others]').innerHTML = '퇴사일 <span class="krs-nw">' + fmt(L) + '</span> · 퇴직일(자격 상실일) <span class="krs-nw">' + fmt(addDays(L, 1)) + '</span>' +
        (pastCount ? '<br>이미 지난 일 ' + pastCount + '개' : '');
      $('[data-note]').textContent = outside ? '2026·2027년이 아닌 날짜는 토·일과 양력 공휴일만 반영했어요(설·추석 등 음력 공휴일과 대체공휴일 미반영).' : '';
      $('[data-note]').hidden = !outside;

      lastText = '[퇴사 후 할 일 체크리스트]\n퇴사일(마지막 근무일): ' + fmt(L) + '\n퇴사 사유: ' + (state.reason === 'inv' ? '권고사직·계약만료 등' : '개인 사정') +
        ' / 재취업: ' + (state.job === 'yes' ? '정해짐' : '아직 없음') + '\n\n' + copy.join('\n') + '\n\n(토·일·공휴일이면 다음 평일 기준, 기관에서 최종 확인)';
    }

    function hide(text, bad) {
      result.classList.remove('krs-show');
      msg.textContent = text || '';
      lastI.classList.toggle('krs-bad', !!bad);
    }

    function calc() {
      if (!lastI.value) return hide('');
      var L = parse(lastI.value);
      if (!L) return hide('날짜를 다시 확인해 주세요.', true);
      if (lastI.value < MIN || lastI.value > MAX) return hide('2025. 1. 1.부터 2027. 12. 31. 사이 날짜를 넣어 주세요.', true);
      msg.textContent = '';
      lastI.classList.remove('krs-bad');
      render(L);
      result.classList.add('krs-show');
    }

    $$('[data-group]').forEach(function (g) {
      g.addEventListener('click', function (e) {
        var b = e.target.closest('.krs-chip');
        if (!b) return;
        state[g.getAttribute('data-group')] = b.getAttribute('data-v');
        Array.prototype.forEach.call(g.querySelectorAll('.krs-chip'), function (c) {
          var on = c === b; c.classList.toggle('krs-on', on); c.setAttribute('aria-pressed', on ? 'true' : 'false');
        });
        calc();
      });
    });

    listEl.addEventListener('change', function (e) {
      var c = e.target;
      if (!c.classList || !c.classList.contains('krs-check')) return;
      done[c.getAttribute('data-id')] = c.checked;
      var li = c.closest('.krs-item');
      if (li) li.classList.toggle('krs-done', c.checked);
      var L = parse(lastI.value);
      if (L) { var y = window.scrollY; render(L); window.scrollTo(0, y); var again = root.querySelector('.krs-check[data-id="' + c.getAttribute('data-id') + '"]'); if (again) again.focus(); }
    });

    lastI.addEventListener('input', calc);
    lastI.addEventListener('change', calc);

    function setToday() {
      var t = today();
      lastI.value = t.getFullYear() + '-' + ('0' + (t.getMonth() + 1)).slice(-2) + '-' + ('0' + t.getDate()).slice(-2);
    }

    $('[data-reset]').addEventListener('click', function () {
      done = {}; setToday();
      state = { reason: 'inv', job: 'no', dep: 'unk' };
      $$('[data-group]').forEach(function (g) {
        Array.prototype.forEach.call(g.querySelectorAll('.krs-chip'), function (c, i) {
          c.classList.toggle('krs-on', i === 0); c.setAttribute('aria-pressed', i === 0 ? 'true' : 'false');
        });
      });
      calc(); lastI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function ok() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); ok(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(ok, fallback);
      else fallback();
    });

    setToday();
    calc();
  })();
  </script>
</div>
