    function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
    function ddText(o, now) {
      var n = diff(now, o.date);
      if (o.kind === 'info') return n > 0 ? 'D-' + n : (n === 0 ? '오늘' : '이미 생겼어요');
      if (n > 0) return 'D-' + n;
      if (n === 0) return 'D-day';
      return o.kind === 'due' ? '기한 지났어요' : n * -1 + '일 지남';
    }
    function whenLabel(o) {
      if (o.kind === 'due') return '까지';
      if (o.needContract) return '';
      if (o.kind === 'info') return '0시부터';
      if (o.id === 'hug') return '부터 바로';
      return o.when || '';
    }
    var LVL = { must: ['필수', 'kmo-b-must'], rec: ['권장', 'kmo-b-rec'], info: ['확인', 'kmo-b-info'] };

    function render(now) {
      list.textContent = '';
      items.forEach(function (o) {
        var n = diff(now, o.date), past = n < 0 && o.kind !== 'info';
        var li = el('li', 'kmo-item' + (past ? ' kmo-past' : '') + (checked[o.id] ? ' kmo-done' : ''));
        var head = el('label', 'kmo-head');
        var cb = el('input', 'kmo-check'); cb.type = 'checkbox'; cb.checked = !!checked[o.id];
        cb.addEventListener('change', function () { checked[o.id] = cb.checked; li.classList.toggle('kmo-done', cb.checked); updateDone(); makeText(); });
        var hb = el('div', 'kmo-hbody'), when = el('p', 'kmo-when');
        var bd = el('span', 'kmo-badge ' + LVL[o.lvl][1], LVL[o.lvl][0]);
        when.appendChild(bd);
        if (o.needContract) when.appendChild(el('span', '', '계약일을 넣으면 기한을 계산해요'));
        else {
          when.appendChild(el('span', 'kmo-date', fmt(o.date)));
          when.appendChild(el('span', '', whenLabel(o)));
          when.appendChild(el('span', 'kmo-dd' + (n < 0 && o.kind === 'due' ? ' kmo-over' : ''), ddText(o, now)));
        }
        hb.appendChild(when);
        hb.appendChild(el('p', 'kmo-name', o.name));
        head.appendChild(cb); head.appendChild(hb); li.appendChild(head);
        var lines = el('div', 'kmo-lines');
        function line(k, v, cls) { var p = el('p', cls || ''); p.appendChild(el('span', '', k)); p.appendChild(document.createTextNode(v)); lines.appendChild(p); }
        var L = o.labels || ['어디서', '준비물', '놓치면'];
        line(L[0], o.where); line(L[1], o.docs); line(L[2], o.miss);
        if (o.moved) line('참고', '마지막 날이 주말·공휴일이라 다음 평일까지로 계산했어요.');
        if (o.assumed) line('참고', '잔금일을 넣지 않아 이사일을 잔금일로 보고 계산했어요.');
        if (past && o.late) line('지났어요', o.late, 'kmo-latenote');
        else if (past) line('지났어요', '권장 시기는 지났지만 아직 안 했다면 지금 하세요.', 'kmo-latenote');
        li.appendChild(lines);
        list.appendChild(li);
      });
      $('[data-total]').textContent = items.length;
      updateDone();
    }
    function updateDone() { var c = 0; items.forEach(function (o) { if (checked[o.id]) c++; }); $('[data-done]').textContent = c; }

    function makeText() {
      var now = today(), move = parse(moveI);
      var t = '[이사 행정 타임라인]\n이사일: ' + fmt(move) + ' · ' + TYPE_NAME[state.type] + '\n';
      items.forEach(function (o) {
        t += '\n' + (checked[o.id] ? '[x] ' : '[ ] ') + (o.needContract ? '계약일부터 30일' : fmt(o.date) + ' ' + whenLabel(o) + ' (' + ddText(o, now) + ')') + ' - ' + o.name;
      });
