    }

    function hide(text) { result.classList.remove('kmo-show'); msg.textContent = text || ''; }

    function calc() {
      [moveI, conI, balI].forEach(function (i) { i.classList.toggle('kmo-empty', !i.value); });
      var move = parse(moveI), contract = parse(conI), balance = parse(balI);
