      if (contract && contract > move) return hide('계약일이 이사일보다 뒤예요.');
      if (contract && balance && contract > balance) return hide('계약일이 잔금일보다 뒤예요.');
      if (balance && Math.abs(diff(balance, move)) > 365) return hide('잔금일과 이사일이 1년 넘게 차이 나요. 날짜를 확인해 주세요.');
      msg.textContent = '';
      items = build(move, contract, balance);
      var now = today(), first = items.filter(function (o) { return o.id === 'move'; })[0];
      var n = diff(now, first.date), big = $('[data-big]');
