      $('[data-sub1]').textContent = fmt(first.date) + '까지' + (first.moved ? ' (주말·공휴일 다음 평일)' : '');
      var sub2 = $('[data-sub2]'), warn = $('[data-warn]');
      sub2.textContent = '';
      if (state.type !== 'buy') {
        sub2.appendChild(document.createTextNode('대항력: '));
