        sub2.appendChild(document.createTextNode('취득세·등기 마감: '));
        sub2.appendChild(el('b', '', fmt(tx.date)));
        warn.hidden = true;
      }
      render(now);
      makeText();
      result.classList.add('kmo-show');
    }

    $$('.kmo-tab').forEach(function (b) {
      b.addEventListener('click', function () {
        state.type = b.getAttribute('data-type');
        $$('.kmo-tab').forEach(function (x) { var on = x === b; x.classList.toggle('kmo-on', on); x.setAttribute('aria-checked', on ? 'true' : 'false'); });
        calc();
      });
    });
    $$('.kmo-chip').forEach(function (b) {
      b.addEventListener('click', function () {
        var k = b.getAttribute('data-opt'); state[k] = !state[k];
        b.classList.toggle('kmo-on', state[k]); b.setAttribute('aria-pressed', state[k] ? 'true' : 'false');
        calc();
      });
    });
    [moveI, conI, balI].forEach(function (i) { i.addEventListener('input', calc); i.addEventListener('change', calc); });

    $('[data-reset]').addEventListener('click', function () {
      moveI.value = iso(today()); conI.value = ''; balI.value = ''; checked = {};
      state = { type: 'jeonse', car: false, school: false };
      $$('.kmo-tab').forEach(function (x, i) { x.classList.toggle('kmo-on', i === 0); x.setAttribute('aria-checked', i === 0 ? 'true' : 'false'); });
      $$('.kmo-chip').forEach(function (x) { x.classList.remove('kmo-on'); x.setAttribute('aria-pressed', 'false'); });
      calc(); moveI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });

    moveI.value = iso(today());
