    @media (max-width:420px){.kjs{padding:18px;border-radius:16px}.kjs .kjs-big{font-size:30px}.kjs .kjs-in{font-size:17px}
      .kjs .kjs-tab{font-size:12.5px}.kjs .kjs-opt{font-size:13.5px}}
