  <script>
  (function () {
    var me = document.currentScript || (function (s) { return s[s.length - 1]; })(document.getElementsByTagName('script'));
    var root = me.closest('[data-kjs]');
    if (!root || root.__kjs) return;
    root.__kjs = true;

    // HUG 전세반환보증(구 전세보증금반환보증) 기준, 2026. 11. 20. 확인
    var LTV = 90;            // 담보인정비율(전세가율) %: (보증금 + 선순위) ≤ 주택가격 × 90% (2023. 5. 1. 신규분부터)
    var OFFICIAL_RATE = 140; // 공시가격 적용비율 % (2023. 1. 1. 신청분부터 150% → 140%)
    var SENIOR_MAX = 60;     // 선순위채권 ≤ 주택가격의 60%
    var SENIOR_MAX_HOUSE = 80; // 단독·다중·다가구: 선순위 임차보증금 포함 80% (그중 보증금 외 채권은 60%)
    var CAP = { metro: 70000, other: 50000 }; // 보증 대상 전세보증금 한도(만원): 수도권 7억, 그 외 5억
    var SCENARIOS = [80, 70]; // 정부 검토 중인 인하안(미확정) 미리 보기
    var MAX = 9999999; // 만원

    var TYPE = {
      apt: { name: '아파트', basis: true, def: 'market', market: '시세', marketSmall: 'KB·부동산원 시세 × 100%', official: '공시가격',
        priceLabel: { market: 'KB시세 (또는 한국부동산원 시세)', official: '공동주택 공시가격' },
        hint: { market: '아파트는 KB시세·한국부동산원 시세가 1순위예요. 시세가 있으면 보통 이 값이 쓰여요.',
          official: '시세가 없는 아파트만 공시가격 × 140%를 써요. 시세가 있으면 시세가 우선이에요.' } },
      ot: { name: '오피스텔', basis: true, def: 'market', market: '시세', marketSmall: 'KB·부동산원 시세 × 100%', official: '기준시가',
        priceLabel: { market: 'KB시세 (또는 한국부동산원 시세)', official: '오피스텔 기준시가 (국세청)' },
        hint: { market: '오피스텔도 KB시세·한국부동산원 시세가 1순위예요.',
          official: '시세가 없으면 홈택스에서 조회한 오피스텔 기준시가 × 140%를 써요.' } },
      villa: { name: '연립·다세대', basis: true, def: 'official', market: '안심전세앱 시세', marketSmall: '하한가 × 100%', official: '공시가격',
        priceLabel: { market: '안심전세앱 시세 하한가', official: '공동주택 공시가격' },
        hint: { market: '연립·다세대는 공시가격 × 140%가 1순위예요. 공시가격이 없을 때 안심전세앱 시세 하한가 등을 봐요.',
          official: '연립·다세대(빌라)는 공시가격 × 140%가 1순위예요. 부동산공시가격알리미에서 조회할 수 있어요.' } },
      house: { name: '단독·다가구', basis: false, def: 'official', official: '공시가격',
        priceLabel: { official: '개별단독주택 공시가격' },
        hint: { official: '단독·다가구는 개별단독주택가격 × 140%를 써요. 부동산공시가격알리미에서 조회할 수 있어요.' } }
    };

    var $ = function (s) { return root.querySelector(s); };
    var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    var priceI = $('[data-price]'), depI = $('[data-dep]'), seniorI = $('[data-senior]'), priorI = $('[data-prior]');
    var msg = $('[data-msg]'), result = $('[data-result]');
    var type = 'apt', region = 'metro', basis = 'market', lastText = '';

    function comma(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
    function num(s) { return s === '' ? NaN : +String(s).replace(/,/g, ''); }
    // 만원 단위 정수 → "3억 5,000만원"
    function man(m) {
      if (m <= 0) return '0원';
      var eok = Math.floor(m / 10000), rest = m % 10000;
      if (!eok) return comma(rest) + '만원';
      return comma(eok) + '억' + (rest ? ' ' + comma(rest) + '만원' : '원');
    }
    // 원 → 만원 미만 버림 표시
    function wonToMan(w) { return man(Math.floor(w / 10000)); }
    function pct(a, b) { return (Math.floor(a / b * 1000 + 1e-9) / 10).toFixed(1) + '%'; }

    function select(attr, val) {
      $$('[' + attr + ']').forEach(function (b) {
        var on = b.getAttribute(attr) === val;
        b.classList.toggle('kjs-on', on);
        b.setAttribute(b.getAttribute('role') === 'tab' ? 'aria-selected' : 'aria-pressed', on);
      });
    }

    function readOne(inp, el, empty) {
      var v = num(inp.value);
      if (v > 0) el.innerHTML = '= <b>' + man(v) + '</b>';
      else el.textContent = empty;
    }
    function readAll() {
      readOne(priceI, $('[data-price-read]'), '만원 단위로 입력하세요. 3억원이면 30,000');
      readOne(depI, $('[data-dep-read]'), '만원 단위로 입력하세요. 2억 5천만원이면 25,000');
      readOne(seniorI, $('[data-senior-read]'), '등기부등본 을구의 근저당 채권최고액 합계예요. 없으면 비워 두거나 0을 넣으세요.');
      readOne(priorI, $('[data-prior-read]'), '다가구는 나보다 먼저 전입·확정일자를 받은 세입자 보증금도 선순위로 빠져요. 없으면 0.');
    }

    function applyType() {
      var t = TYPE[type];
      $('[data-basis-box]').hidden = !t.basis;
      if (!t.basis) basis = 'official';
      if (t.basis) {
        $('[data-market-name]').textContent = t.market;
        $('[data-market-small]').textContent = t.marketSmall;
      }
      $('[data-official-name]').textContent = t.official;
      select('data-basis', basis);
      $('[data-price-label]').textContent = t.priceLabel[basis];
      $('[data-basis-hint]').textContent = t.hint[basis];
      $('[data-prior-box]').hidden = type !== 'house';
    }

    function hide(text, bad) {
      result.classList.remove('kjs-show');
      msg.textContent = text || '';
      $$('.kjs-in').forEach(function (i) { i.classList.toggle('kjs-bad', !!bad && i === bad); });
    }

    function li(ok, text) { return { ok: ok, text: text }; }

    function calc() {
      if (priceI.value === '' || depI.value === '') return hide('');
      var p = num(priceI.value), dep = num(depI.value);
      var senior = seniorI.value === '' ? 0 : num(seniorI.value);
      var prior = type !== 'house' || priorI.value === '' ? 0 : num(priorI.value);
      if (!(p > 0)) return hide('주택가격을 1만원 이상으로 입력해 주세요.', priceI);
      if (!(dep > 0)) return hide('전세보증금을 1만원 이상으로 입력해 주세요.', depI);
      if (p > MAX) return hide('주택가격이 너무 커요. 만원 단위로 입력했는지 확인해 주세요.', priceI);
      if (dep > MAX) return hide('전세보증금이 너무 커요. 만원 단위로 입력했는지 확인해 주세요.', depI);
      if (senior > MAX) return hide('선순위 채권이 너무 커요. 만원 단위로 입력했는지 확인해 주세요.', seniorI);
      if (prior > MAX) return hide('선순위 임차보증금이 너무 커요. 만원 단위로 입력했는지 확인해 주세요.', priorI);
      hide('');

      var t = TYPE[type];
      var rate = basis === 'official' ? OFFICIAL_RATE : 100;
      // 모든 금액을 원 단위 정수로 계산
      var priceW = p * 10000 * rate / 100;              // 인정 주택가격 (1만원 × 정수 % → 원 단위 정수)
      var depW = dep * 10000, seniorW = senior * 10000, priorW = prior * 10000;
      var capMan = CAP[region], capW = capMan * 10000;
      var limitW = Math.floor(priceW * LTV / 100);       // 주택가격 × 90%
      var totalW = depW + seniorW + priorW;
      var room = limitW - seniorW - priorW;
      var maxW = Math.max(0, Math.min(room, capW));

      var checks = [];
      var okCap = depW <= capW;
      checks.push(li(okCap, '보증금 한도: ' + man(dep) + (okCap ? ' ≤ ' : ' > ') + (region === 'metro' ? '수도권 ' : '그 외 지역 ') + man(capMan)));
      var seniorLimW = Math.floor(priceW * SENIOR_MAX / 100);
      var okSenior = seniorW <= seniorLimW;
      checks.push(li(okSenior, '선순위 채권: ' + man(senior) + (okSenior ? ' ≤ ' : ' > ') + '주택가격의 60% (' + wonToMan(seniorLimW) + ')'));
      var okHouse = true;
      if (type === 'house') {
        var houseLimW = Math.floor(priceW * SENIOR_MAX_HOUSE / 100);
        okHouse = seniorW + priorW <= houseLimW;
        checks.push(li(okHouse, '선순위 채권 + 선순위 임차보증금: ' + man(senior + prior) + (okHouse ? ' ≤ ' : ' > ') + '주택가격의 80% (' + wonToMan(houseLimW) + ')'));
      }
      var okLtv = totalW <= limitW;
      checks.push(li(okLtv, '보증금 + 선순위: ' + man(dep + senior + prior) + (okLtv ? ' ≤ ' : ' > ') + '주택가격의 90% (' + wonToMan(limitW) + ')'));
      var ok = okCap && okSenior && okHouse && okLtv;

      var main = $('[data-main]');
      main.classList.toggle('kjs-no', !ok);
      $('[data-big]').textContent = ok ? '가입 가능해 보여요' : '가입이 어려워요';
      var reasons = [];
      if (!okLtv) reasons.push('보증금과 선순위 채권 합계가 주택가격의 90%를 ' + wonToMan(totalW - limitW) + ' 넘어요');
      if (!okCap) reasons.push('보증금이 ' + (region === 'metro' ? '수도권' : '지역') + ' 한도 ' + man(capMan) + '을 넘어요');
      if (!okSenior) reasons.push('선순위 채권이 주택가격의 60%를 넘어요');
      if (!okHouse) reasons.push('선순위 채권과 선순위 임차보증금 합계가 주택가격의 80%를 넘어요');
      $('[data-sub]').textContent = ok
        ? '이 집은 보증금 ' + wonToMan(maxW) + '까지 가입 요건 안이에요'
        : reasons.join(' · ');

      $('[data-v-price]').textContent = wonToMan(priceW);
      $('[data-s-price]').textContent = basis === 'official' ? t.official + ' ' + man(p) + ' × 140%' : t.market + ' ' + man(p) + ' × 100%';
      $('[data-v-max]').textContent = maxW > 0 && okSenior && okHouse ? wonToMan(maxW) : '0원';
      $('[data-s-max]').textContent = !(okSenior && okHouse) ? '선순위 채권 요건부터 넘어서 가입이 안 돼요'
        : room <= 0 ? '선순위만으로 90%를 채워요'
        : (room > capW ? '지역 한도 ' + man(capMan) + ' 적용' : '주택가격 × 90% − 선순위');
      $('[data-v-ratio]').textContent = pct(depW, priceW);
      $('[data-v-debt]').textContent = pct(totalW, priceW);

      var box = $('[data-checks]'); box.innerHTML = '';
      checks.forEach(function (c) { var el = document.createElement('li'); el.className = c.ok ? 'kjs-ok' : 'kjs-x'; el.textContent = c.text; box.appendChild(el); });

      var debt = totalW / priceW * 100, risk = $('[data-risk]'), lvl, rtxt;
      if (debt > LTV) { lvl = 2; rtxt = '위험 신호: 보증금과 선순위 채권이 인정 주택가격의 90%를 넘어요. 집이 경매로 넘어가면 보증금을 다 돌려받기 어려울 수 있는 깡통전세 구간이에요.'; }
      else if (debt >= 80) { lvl = 2; rtxt = '위험 신호: 부채비율이 80% 이상이에요. 지금은 가입 요건 안이지만 집값이 조금만 내려도 보증금이 위험해지고, 비율 기준이 낮아지면 갱신 때 가입이 안 될 수 있어요.'; }
      else if (debt > 70) { lvl = 1; rtxt = '주의: 부채비율이 70%를 넘어요. 보증료율이 더 높은 구간이고, 담보인정비율이 낮아지면 영향을 받을 수 있어요.'; }
      else { lvl = 0; rtxt = '부채비율이 70% 이하로 비교적 여유가 있어요. 그래도 계약 전 등기부등본과 임대인 체납 여부는 꼭 확인하세요.'; }
      if (seniorW > priceW * 0.5 && okSenior) rtxt += ' 선순위 채권이 주택가격의 50%를 넘어 보증료가 10% 할증돼요.';
      risk.className = 'kjs-risk kjs-r' + lvl;
      risk.textContent = rtxt;

      var lines = [];
      lines.push('인정 주택가격: ' + man(p) + ' × ' + rate + '% = ' + wonToMan(priceW));
      lines.push('가입 한도: ' + wonToMan(priceW) + ' × 90% = ' + wonToMan(limitW));
      lines.push('최대 보증금: ' + wonToMan(limitW) + ' − 선순위 ' + man(senior + prior) + ' = ' + (room > 0 ? wonToMan(room) : '0원') +
        (room > capW ? ' → 지역 한도 ' + man(capMan) : '') + (okSenior && okHouse ? '' : ' (선순위 비율 요건 초과로 가입 불가)'));
      var sc = SCENARIOS.map(function (r) {
        var m = Math.max(0, Math.min(Math.floor(priceW * r / 100) - seniorW - priorW, capW));
        return r + '%면 ' + wonToMan(m);
      });
      lines.push('비율이 낮아진다면(검토 중, 미확정): ' + sc.join(' / '));
      var f = $('[data-formula]'); f.innerHTML = '';
      lines.forEach(function (s) { var el = document.createElement('p'); el.textContent = s; f.appendChild(el); });

      result.classList.add('kjs-show');

      lastText = '[전세보증보험(HUG 전세반환보증) 가입 가능 여부]\n' +
        '주택: ' + t.name + ' / ' + (region === 'metro' ? '수도권' : '그 외 지역') + '\n' +
        '인정 주택가격: ' + wonToMan(priceW) + ' (' + (basis === 'official' ? t.official + ' × 140%' : t.market) + ')\n' +
        '전세보증금: ' + man(dep) + ' / 선순위: ' + man(senior + prior) + '\n' +
        '판정: ' + (ok ? '가입 가능해 보여요' : '가입이 어려워요 (' + reasons.join(', ') + ')') + '\n' +
        '가입 가능한 최대 보증금: ' + $('[data-v-max]').textContent + '\n' +
        '전세가율 ' + pct(depW, priceW) + ' / 부채비율 ' + pct(totalW, priceW) + '\n' +
        '※ 2026. 11. 기준 담보인정비율 90%. 최종 심사는 HUG·은행이 해요.';
    }

    $$('[data-type]').forEach(function (b) {
      b.addEventListener('click', function () {
        type = b.getAttribute('data-type'); select('data-type', type);
        basis = TYPE[type].def; applyType(); calc();
      });
    });
    $$('[data-region]').forEach(function (b) { b.addEventListener('click', function () { region = b.getAttribute('data-region'); select('data-region', region); calc(); }); });
    $$('[data-basis]').forEach(function (b) { b.addEventListener('click', function () { basis = b.getAttribute('data-basis'); applyType(); calc(); }); });

    [priceI, depI, seniorI, priorI].forEach(function (inp) {
      inp.addEventListener('input', function () {
        var v = inp.value.replace(/\D/g, '').replace(/^0+(?=\d)/, '').slice(0, 8);
        inp.value = v === '' ? '' : comma(v);
        readAll(); calc();
      });
    });

    $('[data-reset]').addEventListener('click', function () {
      priceI.value = depI.value = seniorI.value = priorI.value = '';
      readAll(); hide(''); priceI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });

    applyType(); readAll();
  })();
  </script>
