          '</li>';
      });
      list.innerHTML = html;
      lastItems = arr; lastBirth = b; lastToday = t;

      var future = diff(t, b) > 0;
      $('[data-main-label]').textContent = future ? '출산 예정일 기준 · 가장 먼저 챙길 마감' : '가장 급한 마감';
      if (next) $('[data-big]').innerHTML = esc(next.st.text) + '<small>' + esc(next.name) + ' · <span class="kbb-date">' + fmt(next.end) + '</span></small>';
      else $('[data-big]').innerHTML = '남은 마감 없음<small>지난 항목도 지금 가능한지 확인해 보세요</small>';
      $('[data-sum]').textContent = '할 일 ' + arr.length + '개 · 남은 일 ' + open + '개 · 시기 지난 일 ' + past + '개';
      result.classList.add('kbb-show');
    }

    function copyText() {
      var b = lastBirth, t = lastToday;
      return '[출산 후 신청할 것 체크리스트]\n출생일: ' + fmt(b) + ' · 기준일: ' + fmt(t) + '\n' +
        lastItems.map(function (it) {
          return (done[it.id] ? '[x] ' : '[ ] ') + it.name + ' — ' + whenText(it) + (it.st.text ? ' (' + it.st.text + ')' : '') + '\n    어디서: ' + it.where;
        }).join('\n') + '\n※ 2026년 11월 기준, 실제 신청 전 각 기관 안내를 확인하세요.';
    }

    list.addEventListener('change', function (e) {
      if (!e.target.classList.contains('kbb-chk')) return;
      var li = e.target.closest('[data-id]'), id = li.getAttribute('data-id');
      done[id] = e.target.checked;
      li.classList.toggle('kbb-done', e.target.checked);
      calc();
    });

    function bind(input, next, len) {
      input.addEventListener('input', function () {
        var v = input.value.replace(/\D/g, '').slice(0, len);
        if (v !== input.value) input.value = v;
        if (next && v.length === len) next.focus();
        if (next === dI && len === 2 && v.length === 1 && +v > 1) dI.focus();
        if (input === dI && v.length === 1 && +v > 3) dI.blur();
        calc();
      });
    }
    bind(yI, mI, 4); bind(mI, dI, 2); bind(dI, null, 2);
    [mI, dI].forEach(function (inp, i) {
      inp.addEventListener('keydown', function (e) {
        if (e.key === 'Backspace' && !inp.value) { e.preventDefault(); (i === 0 ? yI : mI).focus(); }
      });
    });
    yI.addEventListener('paste', function (e) {
      var s = (e.clipboardData || window.clipboardData).getData('text').replace(/\D/g, '');
      if (s.length === 8) { e.preventDefault(); yI.value = s.slice(0, 4); mI.value = String(+s.slice(4, 6)); dI.value = String(+s.slice(6, 8)); calc(); }
    });

    function setToday() { var t = today(); yI.value = t.getFullYear(); mI.value = t.getMonth() + 1; dI.value = t.getDate(); }
    $('[data-today]').addEventListener('click', function () { setToday(); calc(); });

    function group(sel, key, numeric) {
      $$(sel + ' button').forEach(function (btn) {
        btn.addEventListener('click', function () {
          $$(sel + ' button').forEach(function (x) { var on = x === btn; x.classList.toggle('kbb-on', on); x.setAttribute('aria-pressed', on); });
          state[key] = numeric ? +btn.getAttribute('data-v') : btn.getAttribute('data-v');
          calc();
        });
      });
    }
    group('[data-order]', 'order', true);
    group('[data-work]', 'work', false);
    regionI.addEventListener('change', calc);

    $('[data-reset]').addEventListener('click', function () {
      yI.value = mI.value = dI.value = ''; done = {}; hide(''); yI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this, text = copyText();
      function ok() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = text; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); ok(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text).then(ok, fallback);
      else fallback();
    });

    setToday();
    calc();
  })();
  </script>
</div>
<!-- 출산 후 신청할 것 타임라인 위젯 끝 -->
<h2>출산 후 기한 계산법</h2>
<p>대부분의 기한은 <strong>출생일(출산일)을 첫날로 세요</strong>. 그래서 "1개월 이내"는 다음 달 같은 날의 하루 전까지, "60일 이내"는 출생일에 59일을 더한 날까지예요. 다음 달에 같은 날이 없으면(1월 31일생 등) 그 달 마지막 날까지예요.</p>
<ul>
  <li><strong>출생신고</strong> = 출생일 + 1개월 − 1일 (가족관계등록법상 신고기간은 사건 발생일부터 세요)</li>
  <li><strong>부모급여·아동수당 소급 기한</strong> = 출생일 + 59일 (출생일 포함 60일)</li>
  <li><strong>배우자 출산휴가 사용 기한</strong> = 출산일부터 120일 (위젯은 안전하게 출산일 + 119일로 표시)</li>
  <li><strong>첫만남이용권 신청·사용 기한</strong> = 출생일 + 2년 − 1일</li>
  <li><strong>영유아 건강검진 1차</strong> = 출생일 + 14일 ~ 출생일 + 35일</li>
</ul>
<p>예를 들어 <strong>2026년 11월 20일(금)</strong>에 태어났다면 이렇게 돼요.</p>
<ul>
  <li>출생신고: 2026. 12. 19.(토)까지 → 마지막 날이 토요일이라 실제로는 다음 평일까지 인정될 수 있지만, 주민센터가 문을 여는 평일에 미리 하는 게 안전해요.</li>
  <li>부모급여·아동수당: 2027. 1. 18.(월)까지 신청하면 2026년 11월분부터 받아요.</li>
  <li>영유아 건강검진 1차: 2026. 12. 4.(금) ~ 2026. 12. 25.(금)</li>
  <li>배우자 출산휴가: 2027. 3. 19.(금)까지 20일을 나눠 쓰기</li>
  <li>첫만남이용권: 2028. 11. 19.(일)까지 신청하고 다 쓰기</li>
</ul>

