      var mhHint = $('[data-mh-hint]');
      if (weekI.value && w >= 15 && w <= 40) {
        mhHint.innerHTML = '월 기준시간: ' + nw(autoMonthHours(w) + '시간') + ' (주휴 포함 자동 계산) ' + (manualMH ? '' : '<button type="button" class="kau-link" data-mh-on>직접 입력</button>');
      } else mhHint.textContent = '';

      var wageEmpty = mode === 'month' ? !monthI.value : !hourlyI.value;
      if (wageEmpty || !weekI.value || !dayI.value || !leftI.value) return hide('');

      if (!(w > 0)) return hide('주 소정근로시간을 다시 확인해 주세요.', weekI);
      if (w > 40) return hide('주 소정근로시간은 40시간을 넘을 수 없어요. 연장근로는 빼고 입력해 주세요.', weekI);
      if (!(d > 0)) return hide('1일 소정근로시간을 다시 확인해 주세요.', dayI);
      if (d > 8) return hide('1일 소정근로시간은 8시간을 넘을 수 없어요. 연장근로는 빼고 입력해 주세요.', dayI);
      if (d > w) return hide('1일 소정근로시간이 주 소정근로시간보다 길어요. 다시 확인해 주세요.', dayI);

      var left = num(leftI.value);
      if (isNaN(left) || left <= 0) return hide('못 쓴 연차 일수를 0.5일 이상 입력해 주세요.', leftI);
      if (Math.round(left * 2) !== left * 2) return hide('연차 일수는 1일 또는 반차(0.5일) 단위로 입력해 주세요.', leftI);
      if (left > 100) return hide('연차 일수가 너무 커요. 100일 이하로 입력해 주세요.', leftI);

      var main = $('[data-main]'), grid = $('[data-grid]'), formula = $('[data-formula]');

      if (w < 15) {
        msg.textContent = '';
        main.classList.add('kau-no'); grid.hidden = true; formula.hidden = true;
        $('[data-promo-note]').hidden = true;
        $('[data-main-label]').textContent = '연차 유급휴가 대상이 아니에요';
        $('[data-big]').textContent = '주 15시간 미만 근무';
        $('[data-sub]').textContent = '4주 평균 주 15시간 미만인 초단시간 근로자는 법정 연차가 없어요(근로기준법 제18조).';
        lastText = '[연차수당 계산 결과]\n주 소정근로시간 ' + dec(w) + '시간으로 주 15시간 미만이라 법정 연차 대상이 아니에요.';
        result.classList.add('kau-show');
        return;
      }

      var hourly, mh = 0;
      if (mode === 'month') {
        var m = num(monthI.value);
        if (!(m > 0)) return hide('월 통상임금을 다시 확인해 주세요.', monthI);
        if (manualMH) {
          if (!mhI.value) return hide('월 기준시간을 입력하거나 자동으로 바꿔 주세요.', mhI);
          mh = num(mhI.value);
          if (!(mh >= 40 && mh <= 300)) return hide('월 기준시간은 40~300시간 사이로 입력해 주세요.', mhI);
        } else mh = autoMonthHours(w);
        hourly = m / mh;
      } else {
        hourly = num(hourlyI.value);
        if (!(hourly > 0)) return hide('시급을 다시 확인해 주세요.', hourlyI);
      }
      msg.textContent = '';

      var daily = Math.floor(hourly * d);
      var pay = Math.floor(daily * left);
      var leftTxt = dec(left) + '일';

      main.classList.toggle('kau-no', promo);
      grid.hidden = false; formula.hidden = false;
      $('[data-promo-note]').hidden = !promo;
      $('[data-daily]').textContent = won(daily);
      $('[data-hour-v]').textContent = (Math.floor(hourly * 100) / 100).toLocaleString('ko-KR') + '원';
      $('[data-half]').textContent = won(daily * 0.5);
      if (mode === 'month') { $('[data-k4]').textContent = '월 기준시간'; $('[data-v4]').textContent = dec(mh) + '시간'; }
      else { $('[data-k4]').textContent = '1일 소정근로시간'; $('[data-v4]').textContent = dec(d) + '시간'; }

      var f1 = mode === 'month'
        ? '<p>시간당 통상임금 = ' + nw(won(num(monthI.value))) + ' ÷ ' + nw(dec(mh) + '시간') + ' = ' + nw((Math.floor(hourly * 100) / 100).toLocaleString('ko-KR') + '원') + '</p>'
        : '';
      formula.innerHTML = f1 +
        '<p>1일 통상임금 = 시급 × ' + nw(dec(d) + '시간') + ' = ' + nw(won(daily)) + '</p>' +
        '<p>연차수당 = ' + nw(won(daily)) + ' × ' + nw(leftTxt) + ' = ' + nw('<strong>' + won(pay) + '</strong>') + '</p>';

      if (promo) {
        $('[data-main-label]').textContent = '사용촉진을 제대로 받았다면';
        $('[data-big]').innerHTML = '0<small>원</small>';
        $('[data-sub]').textContent = '촉진이 없었다면 ' + won(pay) + '이에요. 아래 조건을 확인하세요.';
      } else {
        $('[data-main-label]').textContent = '미사용 연차수당 (세전)';
        $('[data-big]').innerHTML = fmt(pay) + '<small>원</small>';
        $('[data-sub]').textContent = '1일 ' + won(daily) + ' × ' + leftTxt;
      }

      lastText = '[연차수당 계산 결과]\n' +
        (mode === 'month' ? '월 통상임금: ' + won(num(monthI.value)) + ' (월 ' + dec(mh) + '시간 기준)\n' : '') +
        '시간당 통상임금: ' + (Math.floor(hourly * 100) / 100).toLocaleString('ko-KR') + '원\n' +
        '1일 통상임금: ' + won(daily) + ' (1일 ' + dec(d) + '시간)\n' +
        '못 쓴 연차: ' + leftTxt + '\n' +
        '연차수당(세전): ' + won(pay) +
        (promo ? '\n※ 적법한 사용촉진(제61조)을 받고 사용기간이 끝난 연차라면 지급 의무 없음(0원)' : '');
      result.classList.add('kau-show');
    }

    function moneyInput(inp, max) {
      inp.addEventListener('input', function () {
        var v = inp.value.replace(/\D/g, '').slice(0, max);
        inp.value = v ? (+v).toLocaleString('ko-KR') : '';
        calc();
      });
    }
    moneyInput(monthI, 10);
    moneyInput(hourlyI, 7);
    [weekI, dayI, mhI, leftI].forEach(function (inp) {
      inp.addEventListener('input', function () {
        var v = inp.value.replace(/[^\d.]/g, '').replace(/(\..*)\./g, '$1').slice(0, 5);
        if (v !== inp.value) inp.value = v;
        syncLeftChips(); calc();
      });
    });

    function syncLeftChips() {
      var v = num(leftI.value);
      $$('[data-set]').forEach(function (c) { c.classList.toggle('kau-on', num(c.getAttribute('data-set')) === v); });
    }
    $$('[data-set]').forEach(function (c) {
      c.addEventListener('click', function () { leftI.value = c.getAttribute('data-set'); syncLeftChips(); calc(); });
    });
    $('[data-add]').addEventListener('click', function () {
      var v = num(leftI.value); if (isNaN(v)) v = 0;
      leftI.value = dec(v + 0.5); syncLeftChips(); calc();
    });

    $$('[data-tab]').forEach(function (t) {
      t.addEventListener('click', function () {
        mode = t.getAttribute('data-tab');
        $$('[data-tab]').forEach(function (x) { var on = x === t; x.classList.toggle('kau-on', on); x.setAttribute('aria-selected', on); });
        $('[data-mode-month]').hidden = mode !== 'month';
        $('[data-mode-month2]').hidden = mode !== 'month';
        $('[data-mode-hour]').hidden = mode !== 'hour';
        calc();
      });
    });

    $$('[data-promo]').forEach(function (b) {
      b.addEventListener('click', function () {
        promo = b.getAttribute('data-promo') === '1';
        $$('[data-promo]').forEach(function (x) { var on = x === b; x.classList.toggle('kau-on', on); x.setAttribute('aria-pressed', on); });
        calc();
      });
    });

    root.addEventListener('click', function (e) {
      var t = e.target;
      if (t.closest && t.closest('[data-mh-on]')) {
        manualMH = true; $('[data-mh-box]').hidden = false;
        if (!mhI.value) { var w = num(weekI.value); if (w >= 15 && w <= 40) mhI.value = String(autoMonthHours(w)); }
        mhI.focus(); calc();
      }
    });
    $('[data-mh-off]').addEventListener('click', function () { manualMH = false; $('[data-mh-box]').hidden = true; calc(); });

    $('[data-reset]').addEventListener('click', function () {
      monthI.value = hourlyI.value = leftI.value = mhI.value = '';
      weekI.value = '40'; dayI.value = '8';
      manualMH = false; $('[data-mh-box]').hidden = true;
      promo = false;
      $$('[data-promo]').forEach(function (x) { var on = x.getAttribute('data-promo') === '0'; x.classList.toggle('kau-on', on); x.setAttribute('aria-pressed', on); });
      syncLeftChips(); calc();
      (mode === 'month' ? monthI : hourlyI).focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() {
        var ta = document.createElement('textarea'); ta.value = lastText; ta.setAttribute('readonly', '');
        ta.style.position = 'fixed'; ta.style.opacity = '0';
        document.body.appendChild(ta); ta.select();
        try { document.execCommand('copy'); } catch (e) {}
        ta.remove(); done();
      }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });

    calc();
  })();
  </script>
</div>
<!-- 연차수당 계산기 위젯 끝 -->
<h2>연차수당 계산법</h2>
<p>연차수당(연차휴가 미사용수당)은 근로기준법 제60조에 따라 생긴 연차를 1년 안에 다 쓰지 못했을 때, 못 쓴 날만큼 받는 돈이에요. 1일분은 통상임금으로 계산해요.</p>
<ol>
  <li><strong>시간당 통상임금</strong> = 월 통상임금 ÷ 월 기준시간 (주 40시간이면 209시간)</li>
  <li><strong>1일 통상임금</strong> = 시간당 통상임금 × 1일 소정근로시간 (보통 8시간)</li>
  <li><strong>연차수당</strong> = 1일 통상임금 × 못 쓴 연차 일수 (반차는 0.5일)</li>
</ol>
<p>월 기준시간 209시간은 주 40시간에 유급 주휴 8시간을 더한 48시간에 한 달 평균 주 수(365 ÷ 7 ÷ 12 ≈ 4.345주)를 곱한 값이에요. 주 20시간처럼 짧게 일하면 (20 + 4) × 4.345 ≈ 104시간이 돼요. 시급제라면 시급 × 1일 소정근로시간이 바로 1일 통상임금이에요.</p>
<p>예를 들어 주 5일·하루 8시간 일하고 기본급과 고정수당을 합쳐 월 300만 원을 받는데, 연차 15일 중 9일 반을 쓰고 5.5일이 남았다면 이렇게 계산해요.</p>
<ul>
  <li>시간당 통상임금: 3,000,000원 ÷ 209시간 = <strong>14,354.06원</strong></li>
  <li>1일 통상임금: 14,354.06원 × 8시간 = <strong>114,832원</strong> (원 미만 버림)</li>
  <li>연차수당: 114,832원 × 5.5일 = <strong>631,576원</strong> (세전)</li>
</ul>

<h2>월급별 연차수당 (주 40시간, 1일 8시간)</h2>
<p>월 통상임금 ÷ 209시간 × 8시간으로 계산하고 원 미만을 버린 금액이에요. 세금·4대보험을 빼기 전이에요.</p>
<table>
  <thead><tr><th>월 통상임금</th><th>1일</th><th>5일</th><th>10일</th><th>15일</th></tr></thead>
  <tbody>
    <tr><td>2,156,880원 (2026년 최저임금)</td><td>82,560원</td><td>412,800원</td><td>825,600원</td><td>1,238,400원</td></tr>
    <tr><td>250만 원</td><td>95,693원</td><td>478,465원</td><td>956,930원</td><td>1,435,395원</td></tr>
    <tr><td>300만 원</td><td>114,832원</td><td>574,160원</td><td>1,148,320원</td><td>1,722,480원</td></tr>
    <tr><td>350만 원</td><td>133,971원</td><td>669,855원</td><td>1,339,710원</td><td>2,009,565원</td></tr>
    <tr><td>400만 원</td><td>153,110원</td><td>765,550원</td><td>1,531,100원</td><td>2,296,650원</td></tr>
    <tr><td>500만 원</td><td>191,387원</td><td>956,935원</td><td>1,913,870원</td><td>2,870,805원</td></tr>
  </tbody>
</table>
<p>통상임금에는 기본급과 매달 정해진 금액을 주는 직책·자격·식대 같은 고정수당이 들어가고, 연장·야간·휴일근로수당이나 실적에 따라 달라지는 성과급은 들어가지 않아요. 회사 취업규칙에 월 기준시간이 따로 정해져 있다면 계산기의 <strong>직접 입력</strong>을 눌러 그 시간으로 계산해 보세요.</p>

<h2>연차수당을 받는 경우, 못 받는 경우</h2>
<table>
  <thead><tr><th>상황</th><th>연차수당</th></tr></thead>
  <tbody>
    <tr><td>재직 중, 연차가 생긴 날부터 1년 안에 다 못 썼어요</td><td>받아요. 못 쓴 일수만큼</td></tr>
    <tr><td>회사가 법에 맞게 사용촉진(1차·2차 서면 통보)을 했는데 쓰지 않았어요</td><td>못 받아요 (근로기준법 제61조)</td></tr>
    <tr><td>사용촉진은 했지만 회사가 지정한 휴가일에 일을 시켰어요</td><td>받을 수 있어요</td></tr>
    <tr><td>퇴사해서 남은 연차를 쓸 수 없게 됐어요</td><td>받아요. 퇴직할 때 정산</td></tr>
    <tr><td>1년 계약으로 딱 1년(365일)만 일하고 퇴사했어요</td><td>첫해 월차 11일분만 받아요 (15일은 생기지 않음)</td></tr>
    <tr><td>상시 근로자 5명 미만 사업장이에요</td><td>법정 연차가 없어요 (회사 규정이 있으면 그에 따라)</td></tr>
    <tr><td>4주 평균 주 15시간 미만으로 일해요</td><td>법정 연차가 없어요</td></tr>
  </tbody>
</table>
<p>사용촉진은 연차 사용기간이 끝나기 6개월 전을 기준으로 10일 안에 남은 일수를 알려 주고 사용 시기를 정해 달라고 서면으로 요청한 뒤, 근로자가 시기를 정하지 않으면 사용기간이 끝나기 2개월 전까지 회사가 사용 날짜를 정해 서면으로 알려 주는 절차예요. 입사 첫해 월차는 기간이 짧아서 3개월 전, 1개월 전 기준으로 따로 정해져 있어요. 문자나 구두로만 알렸다면 적법한 촉진으로 보기 어려워요.</p>

<h2>퇴사할 때 연차 정산</h2>
<ul>
  <li><strong>남은 연차는 모두 수당으로:</strong> 퇴사하면 연차를 더 쓸 수 없으니, 퇴사 전까지 생겼는데 못 쓴 연차는 일수만큼 수당으로 받아요. 회사가 사용촉진을 했더라도 사용기간이 끝나기 전에 퇴사했다면 정산 대상이에요.</li>
  <li><strong>1년을 꽉 채운 다음 날까지 다녀야 15일:</strong> 대법원 2021다227100 판결과 고용노동부 행정해석(2021년 12월)에 따라 연차는 1년 근로를 마친 다음 날 생겨요. 1년간 80% 이상 출근했더라도 1년이 되는 날 퇴사하면 그해 15일(또는 가산 일수)은 생기지 않고, 그다음 날까지 재직해야 마지막 해 연차가 생겨 수당으로 받을 수 있어요.</li>
  <li><strong>지급 기한:</strong> 연차수당도 임금이라 퇴직일부터 14일 안에 퇴직금·마지막 월급과 함께 받아야 해요.</li>
  <li><strong>퇴직금과의 관계:</strong> 퇴직 전년도에 생긴 연차를 못 써서 받은 수당은 퇴직금 평균임금에 3/12만큼 들어가요. 퇴사하면서 처음 받는 마지막 해 연차수당은 들어가지 않아요.</li>
</ul>

<h2>자주 묻는 질문</h2>
<h3>연차수당은 월급으로 계산하나요, 통상임금으로 계산하나요?</h3>
<p>통상임금으로 계산해요. 기본급과 매달 고정으로 받는 수당을 합친 월 통상임금을 월 기준시간(주 40시간이면 209시간)으로 나눠 시급을 구하고, 여기에 1일 소정근로시간(보통 8시간)을 곱한 금액이 연차 1일분이에요. 연장근로수당이나 성과급처럼 달마다 달라지는 돈은 넣지 않아요.</p>
<h3>회사에서 연차 사용촉진을 했으면 수당을 정말 못 받나요?</h3>
<p>회사가 근로기준법 제61조의 절차대로 1차(남은 일수 알림과 사용 시기 요청)와 2차(사용 날짜 지정) 서면 통보를 모두 했는데도 쓰지 않아 사용기간이 끝났다면 수당을 받을 수 없어요. 하지만 서면 통보가 빠졌거나 기한이 늦었거나, 지정된 휴가일에 회사가 출근을 시켜 일을 받았다면 수당을 청구할 수 있어요. 사용기간이 끝나기 전에 퇴사해서 못 쓴 연차도 수당으로 정산해요.</p>
<h3>퇴사하면 남은 연차는 어떻게 되나요?</h3>
<p>퇴사 전까지 생겼는데 쓰지 못한 연차는 모두 1일 통상임금 × 남은 일수로 계산해 퇴직일부터 14일 안에 받아요. 1년간 80% 이상 출근했다면 1년 근로를 마친 다음 날까지 재직해야 마지막 해 연차가 생기므로, 입사일 기준으로 1년이 되는 날 바로 퇴사하면 그해 연차는 생기지 않아요.</p>
<h3>연차수당도 퇴직금에 들어가나요?</h3>
<p>들어가요. 퇴직 전년도에 생긴 연차를 못 써서 받은 연차수당은 그 금액의 3/12을 퇴직금 평균임금에 더해 계산해요. 다만 퇴사하면서 처음 생기는 마지막 해 미사용 연차수당은 평균임금에 넣지 않아요. 퇴직금 계산기의 연차수당 칸에 전년도 연차수당을 넣으면 3/12이 자동으로 반영돼요.</p>
<h3>반차나 반반차도 계산할 수 있나요?</h3>
<p>반차는 0.5일로 넣으면 돼요. 계산기에 5.5처럼 입력하거나 반차 버튼을 누르면 0.5일씩 더해져요. 반반차처럼 시간 단위로 남았다면 시급 × 남은 시간으로 계산하면 되고, 2시간이 남았다면 1일 8시간 기준으로 0.25일에 해당하는 금액이에요.</p>

